INSERT INTO exercises (external_id, name, name_fr, body_part, target_muscle, secondary_muscles, equipment, difficulty, instructions, gif_url, image_url, video_url) VALUES
('QjE2DcA','dumbbell step-up split squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand in front of a bench or step with a dumbbell in each hand, palms facing your body.","Step:2 Place your right foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step:3 Step up onto the bench or step with your right foot, pushing through your heel to lift your body up.","Step:4 As you step up, simultaneously lift your left knee towards your chest.","Step:5 Pause at the top of the movement, then slowly lower your left foot back to the ground while keeping your right foot on the bench or step.","Step:6 Repeat the movement with your left foot on the bench or step.","Step:7 Continue alternating between your right and left foot for the desired number of repetitions."}','https://static.exercisedb.dev/media/QjE2DcA.gif','https://static.exercisedb.dev/media/QjE2DcA.gif',NULL),
('qKBpF7I','barbell glute bridge',NULL,'legs','glutes','{"hamstrings","lower back"}','barbell',NULL,'{"Step:1 Start by lying flat on your back on the ground with your knees bent and feet flat on the floor.","Step:2 Place a barbell across your hips, holding it securely with both hands.","Step:3 Engage your glutes and core muscles, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Step:4 Pause for a moment at the top, squeezing your glutes.","Step:5 Slowly lower your hips back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qKBpF7I.gif','https://static.exercisedb.dev/media/qKBpF7I.gif',NULL),
('Ql4g5s8','forward lunge (male) with bench',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet hip-width apart and hands on your hips.","Step:2 Take a big step forward with your right foot, lowering your body into a lunge position.","Step:3 Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Step:4 Push off with your right foot and return to the starting position. Focus on bench movement.","Step:5 Repeat with your left leg, alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ql4g5s8.gif','https://static.exercisedb.dev/media/Ql4g5s8.gif',NULL),
('QLL2gdc','decline sit-up',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Lie on a decline bench with your feet secured and your knees bent.","Step:2 Place your hands behind your head or across your chest.","Step:3 Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/QLL2gdc.gif','https://static.exercisedb.dev/media/QLL2gdc.gif',NULL),
('qLpO4vV','back extension on exercise ball',NULL,'back','spine','{"glutes","hamstrings"}','other',NULL,'{"Step:1 Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.","Step:2 Position your hands behind your head or crossed over your chest.","Step:3 Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qLpO4vV.gif','https://static.exercisedb.dev/media/qLpO4vV.gif',NULL),
('QLRmNeT','dumbbell seated alternate hammer curl on exercise ball',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.","Step:4 Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly lower the dumbbell back to the starting position.","Step:7 Repeat the movement with the opposite arm.","Step:8 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/QLRmNeT.gif','https://static.exercisedb.dev/media/QLRmNeT.gif',NULL),
('qlZUaZ8','dumbbell incline one arm press on exercise ball with extended',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Step:2 Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball. Perform with extended intensity.","Step:3 Hold the dumbbell at shoulder height with your palm facing forward.","Step:4 Press the dumbbell upward until your arm is fully extended.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/qlZUaZ8.gif','https://static.exercisedb.dev/media/qlZUaZ8.gif',NULL),
('qm9veZw','dumbbell lying wide curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qm9veZw.gif','https://static.exercisedb.dev/media/qm9veZw.gif',NULL),
('QOA0FD0','weighted hanging leg-hip raise',NULL,'core','abs','{"hip flexors","lower back"}','other',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your legs up in front of you, keeping them straight.","Step:3 Continue lifting until your legs are parallel to the ground or slightly higher.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/QOA0FD0.gif','https://static.exercisedb.dev/media/QOA0FD0.gif',NULL),
('qOgPVf6','barbell preacher curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Step:2 Grasp the barbell with an underhand grip, slightly wider than shoulder-width apart.","Step:3 Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the barbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qOgPVf6.gif','https://static.exercisedb.dev/media/qOgPVf6.gif',NULL),
('QoHIhPl','behind head chest stretch',NULL,'chest','pectorals','{"shoulders","triceps"}','other',NULL,'{"Step:1 Stand tall with your feet shoulder-width apart.","Step:2 Interlace your fingers behind your head with your elbows pointing outwards.","Step:3 Slowly squeeze your shoulder blades together and push your chest forward.","Step:4 Hold the stretch for 15-30 seconds.","Step:5 Release the stretch and repeat as desired."}','https://static.exercisedb.dev/media/QoHIhPl.gif','https://static.exercisedb.dev/media/QoHIhPl.gif',NULL),
('qOKcgVP','standing calves calf stretch',NULL,'legs','calves','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand facing a wall or sturdy object, about an arm's length away.","Step:2 Place your hands on the wall or object at shoulder height.","Step:3 Step back with one foot, keeping your heel flat on the ground.","Step:4 Bend your front knee slightly and lean forward, keeping your back leg straight.","Step:5 You should feel a stretch in your calf muscle.","Step:6 Hold the stretch for 20-30 seconds.","Step:7 Repeat on the other leg."}','https://static.exercisedb.dev/media/qOKcgVP.gif','https://static.exercisedb.dev/media/qOKcgVP.gif',NULL),
('QoSZo2Y','cable one arm incline press with rigid',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Adjust the cable machine to a low pulley position.","Step:2 Sit on an incline bench facing away from the cable machine.","Step:3 Grasp the handle with one hand and bring it up to shoulder height. Emphasize rigid control.","Step:4 Position your feet firmly on the ground and maintain a stable position.","Step:5 Press the handle forward and upward, extending your arm fully.","Step:6 Pause for a moment at the top, then slowly lower the handle back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/QoSZo2Y.gif','https://static.exercisedb.dev/media/QoSZo2Y.gif',NULL),
('Qoujh3Q','wind sprints',NULL,'core','abs','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Find an open space or a track to perform the exercise.","Step:2 Start by standing with your feet shoulder-width apart.","Step:3 Begin running as fast as you can, pumping your arms and driving your knees up.","Step:4 Continue sprinting for a specific distance or time period.","Step:5 Rest and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Qoujh3Q.gif','https://static.exercisedb.dev/media/Qoujh3Q.gif',NULL),
('qPEzJjA','farmers walk',NULL,'legs','quads','{"calves","forearms","core"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your sides.","Step:2 Keep your back straight and your shoulders back.","Step:3 Take small, controlled steps forward, maintaining an upright posture.","Step:4 Continue walking for the desired distance or time.","Step:5 To finish, stop walking and carefully lower the dumbbells to your sides."}','https://static.exercisedb.dev/media/qPEzJjA.gif','https://static.exercisedb.dev/media/qPEzJjA.gif',NULL),
('QpXqiq8','suspended split squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand facing away from a suspension trainer with your feet shoulder-width apart.","Step:2 Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.","Step:3 Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.","Step:4 Push through your heel to return to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/QpXqiq8.gif','https://static.exercisedb.dev/media/QpXqiq8.gif',NULL),
('Qqi7bko','wide grip pull-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart.","Step:2 Engage your core and squeeze your shoulder blades together.","Step:3 Pull your body up towards the bar until your chin is above the bar.","Step:4 Lower your body back down to the starting position with control.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Qqi7bko.gif','https://static.exercisedb.dev/media/Qqi7bko.gif',NULL),
('QQwxa8g','intermediate style dumbbell preacher curl over exercise ball',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.","Step:3 (intermediate variation) Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/QQwxa8g.gif','https://static.exercisedb.dev/media/QQwxa8g.gif',NULL),
('qRZ5S1N','cable one arm tricep pushdown',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Stand facing a cable machine with a straight bar attachment at chest height.","Step:2 Grasp the bar with an overhand grip and step back to create tension in the cable.","Step:3 Position your feet shoulder-width apart and slightly bend your knees.","Step:4 Keep your back straight and core engaged throughout the exercise.","Step:5 Start with your arm fully extended and perpendicular to the floor.","Step:6 Keeping your upper arm stationary, exhale and push the bar down until your arm is fully extended.","Step:7 Pause for a moment, then inhale and slowly return to the starting position.","Step:8 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/qRZ5S1N.gif','https://static.exercisedb.dev/media/qRZ5S1N.gif',NULL),
('QsSQWbf','band single leg reverse calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','resistance band',NULL,'{"Step:1 Stand with your feet hip-width apart and place the band around the ball of your foot.","Step:2 Hold onto a stable object for balance.","Step:3 Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.","Step:4 Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other leg."}','https://static.exercisedb.dev/media/QsSQWbf.gif','https://static.exercisedb.dev/media/QsSQWbf.gif',NULL),
('QT5Q0nK','dumbbell seated alternate press',NULL,'shoulders','delts','{"triceps","chest"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in each hand, palms facing forward.","Step:2 Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.","Step:3 Press one dumbbell up overhead, fully extending your arm.","Step:4 Lower the dumbbell back down to shoulder height.","Step:5 Repeat with the other arm.","Step:6 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/QT5Q0nK.gif','https://static.exercisedb.dev/media/QT5Q0nK.gif',NULL),
('QTXKWPh','cable pulldown bicep curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a straight bar to the cable machine at the highest setting.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an underhand grip, hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary.","Step:5 Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.","Step:6 Pause for a moment at the bottom of the movement, squeezing your biceps.","Step:7 Inhale and slowly return the bar to the starting position, fully extending your arms.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/QTXKWPh.gif','https://static.exercisedb.dev/media/QTXKWPh.gif',NULL),
('qU8bYp7','rough cable standing one arm triceps extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart, facing the cable machine.","Step:2 Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.","Step:3 Keep your elbow stationary and close to your body.","Step:4 Slowly bend your elbow, lowering the cable handle towards the back of your head.","Step:5 Pause for a moment at the bottom of the movement, then extend your arm back to the starting position. Focus on rough movement.","Step:6 Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."}','https://static.exercisedb.dev/media/qU8bYp7.gif','https://static.exercisedb.dev/media/qU8bYp7.gif',NULL),
('QUDd8WS','oblique crunches floor',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Lie on your back with your knees bent and feet flat on the floor.","Step:2 Place your hands behind your head or cross them over your chest.","Step:3 Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side.","Step:4 Pause for a moment, then lower your shoulder blades back down to the floor.","Step:5 Repeat on the other side, alternating sides with each repetition."}','https://static.exercisedb.dev/media/QUDd8WS.gif','https://static.exercisedb.dev/media/QUDd8WS.gif',NULL),
('qx4fgX7','dumbbell single leg split squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Step:2 Take a step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.","Step:3 Lower your body by bending your front knee and hip, keeping your back knee slightly bent and your back heel off the ground.","Step:4 Continue lowering until your front thigh is parallel to the ground, then push through your front heel to return to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch legs and repeat."}','https://static.exercisedb.dev/media/qx4fgX7.gif','https://static.exercisedb.dev/media/qx4fgX7.gif',NULL),
('qXTaZnJ','barbell full squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:2 Hold the barbell across your upper back, resting it on your traps or rear delts.","Step:3 Engage your core and keep your chest up as you begin to lower your body down.","Step:4 Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Step:5 Lower yourself until your thighs are parallel to the ground or slightly below.","Step:6 Keep your knees in line with your toes and your weight in your heels.","Step:7 Drive through your heels to stand back up, extending your hips and knees.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qXTaZnJ.gif','https://static.exercisedb.dev/media/qXTaZnJ.gif',NULL),
('QY39eBr','seated piriformis stretch',NULL,'legs','glutes','{"hamstrings"}','body weight',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you.","Step:2 Bend your right knee and place your right foot on the outside of your left knee.","Step:3 Place your left elbow on the outside of your right knee and gently twist your torso to the right.","Step:4 Hold the stretch for 20-30 seconds, then switch sides and repeat."}','https://static.exercisedb.dev/media/QY39eBr.gif','https://static.exercisedb.dev/media/QY39eBr.gif',NULL),
('Qyk5J3p','dumbbell cross body hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your body.","Step:2 Keep your elbows close to your torso and your upper arms stationary.","Step:3 Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.","Step:4 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Qyk5J3p.gif','https://static.exercisedb.dev/media/Qyk5J3p.gif',NULL),
('QyO6Uma','smith machine reverse decline close grip bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the smith machine to a decline position.","Step:2 Lie down on the bench with your feet secured under the foot pads.","Step:3 Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Step:5 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/QyO6Uma.gif','https://static.exercisedb.dev/media/QyO6Uma.gif',NULL),
('QYysSLV','landmine 180',NULL,'core','abs','{"obliques","quadriceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the barbell with both hands in front of your chest.","Step:2 Bend your knees slightly and rotate your torso to the right, swinging the barbell down towards your right hip.","Step:3 As you reach the bottom of the movement, quickly reverse the motion and rotate your torso to the left, swinging the barbell up and across your body towards your left shoulder.","Step:4 Continue this twisting motion, alternating sides, for the desired number of repetitions."}','https://static.exercisedb.dev/media/QYysSLV.gif','https://static.exercisedb.dev/media/QYysSLV.gif',NULL),
('QZFv5ui','dumbbell one arm press on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps","core"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.","Step:3 Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/QZFv5ui.gif','https://static.exercisedb.dev/media/QZFv5ui.gif',NULL),
('r0z6xzQ','barbell pendlay row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Bend forward at the hips, keeping your back straight and your chest up.","Step:3 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Pull the barbell towards your upper abdomen, squeezing your shoulder blades together.","Step:5 Lower the barbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/r0z6xzQ.gif','https://static.exercisedb.dev/media/r0z6xzQ.gif',NULL),
('R1WYG5D','suspended reverse crunch',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.","Step:3 Pause for a moment at the top, then slowly lower your knees back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/R1WYG5D.gif','https://static.exercisedb.dev/media/R1WYG5D.gif',NULL),
('r1XNRYB','band assisted pull-up',NULL,'back','lats','{"biceps","forearms"}','resistance band',NULL,'{"Step:1 Attach the band to a pull-up bar or sturdy anchor point.","Step:2 Step onto the band and grip the bar with your palms facing away from you, hands slightly wider than shoulder-width apart.","Step:3 Hang with your arms fully extended, keeping your core engaged and your shoulders down and back.","Step:4 Pull your body up towards the bar by squeezing your shoulder blades together and driving your elbows down towards your hips.","Step:5 Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/r1XNRYB.gif','https://static.exercisedb.dev/media/r1XNRYB.gif',NULL),
('r29jP7S','dumbbell seated calf raise',NULL,'legs','calves','{"hamstrings"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Step:2 Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.","Step:3 Hold onto the dumbbell for stability.","Step:4 Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Step:5 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/r29jP7S.gif','https://static.exercisedb.dev/media/r29jP7S.gif',NULL),
('r4RZKpF','dumbbell one arm fly on exercise ball improved',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Step:2 Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.","Step:3 Extend your arm with the dumbbell straight up above your chest, palm facing inwards.","Step:4 Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Step:5 Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms. Focus on improved movement."}','https://static.exercisedb.dev/media/r4RZKpF.gif','https://static.exercisedb.dev/media/r4RZKpF.gif',NULL),
('r5DgrW9','dumbbell supported squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Step:2 Keeping your chest up and core engaged, slowly lower your body down by bending your knees and pushing your hips back.","Step:3 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:4 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/r5DgrW9.gif','https://static.exercisedb.dev/media/r5DgrW9.gif',NULL),
('R5swFnc','cambered bar lying row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.","Step:2 Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:3 With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.","Step:4 Pull the barbell towards your chest, squeezing your shoulder blades together.","Step:5 Lower the barbell back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/R5swFnc.gif','https://static.exercisedb.dev/media/R5swFnc.gif',NULL),
('r7cT9YD','assisted motion russian twist',NULL,'core','abs','{"obliques","lower back"}','medicine ball',NULL,'{"Step:1 Sit on the ground with your knees bent and feet flat on the floor.","Step:2 Hold the medicine ball with both hands in front of your chest.","Step:3 Lean back slightly, engaging your abs and keeping your back straight.","Step:4 Slowly twist your torso to the right, bringing the medicine ball towards the right side of your body.","Step:5 Pause for a moment, then twist your torso to the left, bringing the medicine ball towards the left side of your body.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/r7cT9YD.gif','https://static.exercisedb.dev/media/r7cT9YD.gif',NULL),
('RaflbWD','dumbbell incline curl v. 2',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RaflbWD.gif','https://static.exercisedb.dev/media/RaflbWD.gif',NULL),
('rbu5UUb','cross body crunch',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat on the other side, bringing your left elbow towards your right knee.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/rbu5UUb.gif','https://static.exercisedb.dev/media/rbu5UUb.gif',NULL),
('rDAiRf9','dumbbell incline one arm press',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Step:2 Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.","Step:3 Press the dumbbell upward and slightly inward, extending your arm fully.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/rDAiRf9.gif','https://static.exercisedb.dev/media/rDAiRf9.gif',NULL),
('reFHapa','dumbbell decline twist fly',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Lie down on a decline bench with your head lower than your hips.","Step:2 Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.","Step:3 Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Step:4 As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.","Step:5 Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/reFHapa.gif','https://static.exercisedb.dev/media/reFHapa.gif',NULL),
('REGM1dE','dumbbell one arm decline chest press',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Step:2 Place your feet flat on the ground and keep your back pressed against the bench.","Step:3 Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/REGM1dE.gif','https://static.exercisedb.dev/media/REGM1dE.gif',NULL),
('rEhi2o5','dumbbell lying supination on floor',NULL,'arms','forearms','{"biceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.","Step:2 Rotate your palms to face up, keeping your elbows close to your sides.","Step:3 Slowly curl the dumbbells towards your shoulders, squeezing your forearms.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/rEhi2o5.gif','https://static.exercisedb.dev/media/rEhi2o5.gif',NULL),
('REXmfVC','sledge hammer',NULL,'core','abs','{"forearms","shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.","Step:2 Engage your core and keep your back straight.","Step:3 Swing the sledge hammer down towards the ground, using your core and upper body strength.","Step:4 As you swing down, pivot your hips and transfer the force to the hammer.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/REXmfVC.gif','https://static.exercisedb.dev/media/REXmfVC.gif',NULL),
('rg59QCH','kettlebell one arm floor press',NULL,'chest','pectorals','{"triceps","shoulders"}','kettlebell',NULL,'{"Step:1 Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Step:2 Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.","Step:3 Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.","Step:4 Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/rg59QCH.gif','https://static.exercisedb.dev/media/rg59QCH.gif',NULL),
('RgJDRR1','barbell wide-grip upright row',NULL,'shoulders','delts','{"traps","biceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Step:2 Let the barbell hang in front of your thighs, arms fully extended.","Step:3 Keeping your back straight, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Step:4 Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RgJDRR1.gif','https://static.exercisedb.dev/media/RgJDRR1.gif',NULL),
('RGLscZM','smith low bar squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.","Step:2 Stand with your feet shoulder-width apart, toes slightly turned outwards.","Step:3 Step under the bar and position it across your upper back, resting it on your traps.","Step:4 Grip the bar with your hands slightly wider than shoulder-width apart.","Step:5 Unrack the bar by straightening your legs and stepping back from the rack.","Step:6 Take a deep breath and brace your core.","Step:7 Initiate the squat by pushing your hips back and bending your knees.","Step:8 Lower your body until your thighs are parallel to the ground or slightly below.","Step:9 Keep your chest up and your back straight throughout the movement.","Step:10 Drive through your heels to stand back up, extending your hips and knees.","Step:11 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RGLscZM.gif','https://static.exercisedb.dev/media/RGLscZM.gif',NULL),
('rGwhJ5o','barbell standing leg calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place a barbell across your upper back.","Step:2 Raise your heels off the ground as high as possible, using your calves.","Step:3 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/rGwhJ5o.gif','https://static.exercisedb.dev/media/rGwhJ5o.gif',NULL),
('RJa4tCo','battling ropes',NULL,'shoulders','delts','{"forearms","core"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold one end of the rope in each hand, with your palms facing each other.","Step:3 Raise your arms to shoulder height, keeping your elbows slightly bent.","Step:4 Begin making alternating waves with the ropes by rapidly raising and lowering each arm.","Step:5 Continue for the desired duration or number of repetitions."}','https://static.exercisedb.dev/media/RJa4tCo.gif','https://static.exercisedb.dev/media/RJa4tCo.gif',NULL),
('RJgzwny','mountain climber',NULL,'cardio','cardiovascular system','{"core","shoulders","triceps"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest.","Step:3 Continue alternating legs in a running motion, keeping your hips low and your core engaged.","Step:4 Maintain a steady pace and breathe evenly throughout the exercise.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RJgzwny.gif','https://static.exercisedb.dev/media/RJgzwny.gif',NULL),
('rjiM4L3','walking on incline treadmill',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the incline level on the treadmill to your desired intensity.","Step:2 Stand on the treadmill with your feet shoulder-width apart.","Step:3 Start walking at a comfortable pace, ensuring that you maintain proper form.","Step:4 Engage your core muscles and keep your back straight throughout the exercise.","Step:5 Continue walking on the incline treadmill for the desired duration of your cardio workout.","Step:6 Gradually decrease the incline and speed of the treadmill to cool down before stopping."}','https://static.exercisedb.dev/media/rjiM4L3.gif','https://static.exercisedb.dev/media/rjiM4L3.gif',NULL),
('rjtuP6X','walk elliptical cross trainer',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes","calves"}','elliptical machine',NULL,'{"Step:1 Adjust the resistance level and incline of the elliptical machine to your desired settings.","Step:2 Step onto the pedals of the machine and grip the handles lightly.","Step:3 Begin by pushing down with your feet and pulling the handles towards your body.","Step:4 Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.","Step:5 Maintain a steady pace and keep your core engaged throughout the exercise.","Step:6 Continue for the desired duration of your cardio workout.","Step:7 Gradually decrease the intensity and speed of the machine before stepping off."}','https://static.exercisedb.dev/media/rjtuP6X.gif','https://static.exercisedb.dev/media/rjtuP6X.gif',NULL),
('rkg41Fb','twin handle parallel grip lat pulldown',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Adjust the seat height and position yourself facing the cable machine.","Step:2 Grasp the handles with an overhand grip, hands shoulder-width apart.","Step:3 Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.","Step:4 Lean back slightly and keep your chest up, maintaining a neutral spine.","Step:5 Pull the handles down towards your upper chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Step:7 Slowly release the handles and return to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/rkg41Fb.gif','https://static.exercisedb.dev/media/rkg41Fb.gif',NULL),
('RKjH6Lt','side bridge v. 2',NULL,'core','abs','{"obliques","glutes"}','body weight',NULL,'{"Step:1 Lie on your side with your legs extended and stacked on top of each other.","Step:2 Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.","Step:3 Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Step:4 Hold this position for the desired amount of time.","Step:5 Lower your hips back down to the starting position.","Step:6 Repeat on the other side."}','https://static.exercisedb.dev/media/RKjH6Lt.gif','https://static.exercisedb.dev/media/RKjH6Lt.gif',NULL),
('rmEukuS','single leg bridge with outstretched leg',NULL,'legs','glutes','{"hamstrings","quadriceps"}','body weight',NULL,'{"Step:1 Lie on your back with your knees bent and feet flat on the ground.","Step:2 Extend one leg straight out in front of you.","Step:3 Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Step:4 Hold for a moment at the top, then slowly lower your hips back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/rmEukuS.gif','https://static.exercisedb.dev/media/rmEukuS.gif',NULL),
('RoV1Rfa','assisted seated pectoralis major stretch with stability ball',NULL,'chest','pectorals','{"shoulders","triceps"}','other',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your back straight.","Step:2 Hold a stability ball with both hands and extend your arms straight out in front of you.","Step:3 Slowly lower the stability ball towards your chest, feeling a stretch in your pectoral muscles.","Step:4 Hold the stretch for a few seconds, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RoV1Rfa.gif','https://static.exercisedb.dev/media/RoV1Rfa.gif',NULL),
('rQhGcin','frog planche',NULL,'core','abs','{"shoulders","chest","triceps"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands shoulder-width apart and your feet together.","Step:2 Bend your elbows and lower your body towards the ground, keeping your back straight.","Step:3 As you lower your body, lift your feet off the ground and bring your knees towards your chest.","Step:4 Hold this position for a few seconds, then extend your legs back out and push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/rQhGcin.gif','https://static.exercisedb.dev/media/rQhGcin.gif',NULL),
('RQNVT10','assisted lying gluteus and piriformis stretch',NULL,'legs','glutes','{"hamstrings"}','other',NULL,'{"Step:1 Lie on your back with your legs extended.","Step:2 Bend your right knee and place your right ankle on your left thigh, just above the knee.","Step:3 Grasp your left thigh with both hands and gently pull it towards your chest.","Step:4 Hold the stretch for 20-30 seconds.","Step:5 Release the stretch and repeat on the other side."}','https://static.exercisedb.dev/media/RQNVT10.gif','https://static.exercisedb.dev/media/RQNVT10.gif',NULL),
('RqOtqD7','cable reverse crunch',NULL,'core','abs','{"hip flexors"}','cable',NULL,'{"Step:1 Attach a cable to a low pulley and lie down facing up on a mat.","Step:2 Hold the cable with both hands and extend your arms straight up towards the ceiling.","Step:3 Bend your knees and lift your legs up, bringing your thighs towards your chest.","Step:4 While keeping your upper body stable, curl your pelvis up towards your chest, lifting your hips off the mat.","Step:5 Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RqOtqD7.gif','https://static.exercisedb.dev/media/RqOtqD7.gif',NULL),
('rQxwMxO','handstand push-up',NULL,'arms','triceps','{"shoulders","chest","core"}','body weight',NULL,'{"Step:1 Find a wall and face away from it, standing a few feet away.","Step:2 Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.","Step:3 Bend your elbows and lower your head towards the ground, keeping your body in a straight line.","Step:4 Push through your hands and extend your arms to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/rQxwMxO.gif','https://static.exercisedb.dev/media/rQxwMxO.gif',NULL),
('rR0LJzx','dumbbell romanian deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Step:2 Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your knees to bend slightly.","Step:3 Lower the dumbbells until you feel a stretch in your hamstrings, then push through your heels and engage your glutes to return to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/rR0LJzx.gif','https://static.exercisedb.dev/media/rR0LJzx.gif',NULL),
('Rr7S3yg','dumbbell front raise v. 2',NULL,'shoulders','delts','{"trapezius","biceps"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Step:2 Keep your back straight and engage your core.","Step:3 Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Rr7S3yg.gif','https://static.exercisedb.dev/media/Rr7S3yg.gif',NULL),
('RrLske5','bench dip (knees bent)',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Step:2 Slide your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.","Step:3 Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RrLske5.gif','https://static.exercisedb.dev/media/RrLske5.gif',NULL),
('RRWFUcw','dumbbell lunge',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Step:2 Take a step forward with your right foot, lowering your body into a lunge position.","Step:3 Keep your back straight and your chest up as you lower your body.","Step:4 Push through your right heel to return to the starting position.","Step:5 Repeat with your left leg.","Step:6 Alternate legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/RRWFUcw.gif','https://static.exercisedb.dev/media/RRWFUcw.gif',NULL),
('rseLfH3','kettlebell extended range one arm press on floor',NULL,'chest','pectorals','{"triceps","shoulders"}','kettlebell',NULL,'{"Step:1 Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Step:2 Hold a kettlebell in one hand, with your palm facing towards your feet.","Step:3 Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Step:4 Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/rseLfH3.gif','https://static.exercisedb.dev/media/rseLfH3.gif',NULL),
('RSOsp5d','dumbbell standing around world',NULL,'shoulders','delts','{"triceps","forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Step:2 Extend your arms straight out to the sides at shoulder height, palms facing down.","Step:3 Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.","Step:4 Continue the circular motion, bringing the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RSOsp5d.gif','https://static.exercisedb.dev/media/RSOsp5d.gif',NULL),
('Rsxr3xl','one arm against wall compressed',NULL,'back','lats','{"shoulders","triceps"}','body weight',NULL,'{"Step:1 Stand facing a wall with your feet shoulder-width apart.","Step:2 Extend one arm straight out in front of you and place your palm against the wall.","Step:3 Engage your core and lean your body forward, keeping your arm straight and your back flat. Maintain compressed form throughout.","Step:4 Slowly push against the wall with your palm, activating your lat muscles.","Step:5 Hold the position for a few seconds, then release and repeat with the other arm."}','https://static.exercisedb.dev/media/Rsxr3xl.gif','https://static.exercisedb.dev/media/Rsxr3xl.gif',NULL),
('rTbyBYV','exercise ball lying side lat stretch',NULL,'back','lats','{"shoulders","triceps"}','other',NULL,'{"Step:1 Lie on your side with your legs extended and your head supported by the stability ball.","Step:2 Place your top arm on the ball for stability.","Step:3 Reach your top arm overhead and allow your torso to rotate slightly.","Step:4 Feel the stretch in your lat muscles on the side of your body.","Step:5 Hold the stretch for 20-30 seconds, then switch sides and repeat."}','https://static.exercisedb.dev/media/rTbyBYV.gif','https://static.exercisedb.dev/media/rTbyBYV.gif',NULL),
('RtyAsy1','arms apart circular toe touch (male)',NULL,'legs','glutes','{"hamstrings","quadriceps","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and arms extended to the sides.","Step:2 Keeping your legs straight, bend forward at the waist and reach down towards your toes with your right hand.","Step:3 As you reach down, simultaneously lift your left leg straight up behind you, maintaining balance.","Step:4 Return to the starting position and repeat the movement with your left hand reaching towards your toes and your right leg lifting up behind you.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/RtyAsy1.gif','https://static.exercisedb.dev/media/RtyAsy1.gif',NULL),
('rUXfn3R','lever back extension',NULL,'back','spine','{"glutes","hamstrings"}','machine',NULL,'{"Step:1 Adjust the machine to fit your body size and range of motion.","Step:2 Sit on the machine with your back against the pad and your feet secured.","Step:3 Place your hands on the handles or grip bars.","Step:4 Engage your core and slowly lean forward, allowing your back to round slightly.","Step:5 Pause for a moment at the bottom position, feeling a stretch in your lower back.","Step:6 Using your back muscles, slowly raise your torso back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/rUXfn3R.gif','https://static.exercisedb.dev/media/rUXfn3R.gif',NULL),
('RVwzP10','cable pulldown',NULL,'back','lats','{"biceps","forearms"}','cable',NULL,'{"Step:1 Adjust the cable pulldown machine so that the seat is at a comfortable height and the knee pad is secured.","Step:2 Sit on the seat with your back straight and your feet flat on the ground.","Step:3 Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Lean back slightly and engage your core.","Step:5 Pull the cable bar down towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RVwzP10.gif','https://static.exercisedb.dev/media/RVwzP10.gif',NULL),
('rWoBmi5','korean dips',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Position yourself between two parallel bars with your arms extended and supporting your body weight.","Step:2 Lower your body by bending your elbows until your upper arms are parallel to the ground.","Step:3 Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/rWoBmi5.gif','https://static.exercisedb.dev/media/rWoBmi5.gif',NULL),
('RxayqAZ','dumbbell close-grip press',NULL,'arms','triceps','{"chest","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Step:2 Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Step:3 Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Step:4 As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","Step:5 As you exhale, use your triceps to lift the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/RxayqAZ.gif','https://static.exercisedb.dev/media/RxayqAZ.gif',NULL),
('RYcV1kH','barbell squat jump step rear lunge',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Step:2 Lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Explode upwards, jumping off the ground as high as you can.","Step:4 Land softly on your feet and immediately step back with one leg into a reverse lunge.","Step:5 Lower your body down until your front thigh is parallel to the ground, keeping your back straight.","Step:6 Push through your front heel to return to the starting position.","Step:7 Repeat the jump and lunge sequence on the other leg.","Step:8 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/RYcV1kH.gif','https://static.exercisedb.dev/media/RYcV1kH.gif',NULL),
('rZ80Gbp','cable seated one arm concentration curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Sit on a bench with your feet flat on the floor and your back straight.","Step:2 Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.","Step:3 Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.","Step:4 Pause for a moment at the top of the movement, squeezing your biceps.","Step:5 Slowly lower the cable handle back to the starting position while inhaling.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/rZ80Gbp.gif','https://static.exercisedb.dev/media/rZ80Gbp.gif',NULL),
('s0HKO2I','bodyweight kneeling triceps extension',NULL,'arms','triceps','{"shoulders","chest"}','body weight',NULL,'{"Step:1 Kneel down on the ground with your knees hip-width apart.","Step:2 Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.","Step:3 Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.","Step:4 Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.","Step:5 Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/s0HKO2I.gif','https://static.exercisedb.dev/media/s0HKO2I.gif',NULL),
('S1JXDAG','band seated twist',NULL,'core','abs','{"obliques"}','resistance band',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you and your back straight.","Step:2 Wrap the band around your waist and hold the ends with both hands.","Step:3 Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Step:4 Pause for a moment at the end of the twist, then slowly return to the starting position.","Step:5 Repeat the twist to the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/S1JXDAG.gif','https://static.exercisedb.dev/media/S1JXDAG.gif',NULL),
('s34Y4LR','weighted seated twist (on stability ball)',NULL,'core','abs','{"obliques","lower back"}','other',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Hold a weight plate or dumbbell with both hands close to your chest.","Step:3 Engage your core and slowly rotate your torso to one side, keeping your hips stable.","Step:4 Pause for a moment at the end of the rotation, then slowly return to the starting position.","Step:5 Repeat the rotation to the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/s34Y4LR.gif','https://static.exercisedb.dev/media/s34Y4LR.gif',NULL),
('S37C94C','kettlebell one arm jerk',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Step:2 Bend your knees slightly and engage your core.","Step:3 Press the kettlebell overhead in a straight line, fully extending your arm.","Step:4 As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.","Step:5 As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.","Step:6 Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.","Step:7 Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.","Step:8 Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/S37C94C.gif','https://static.exercisedb.dev/media/S37C94C.gif',NULL),
('S4pwGlc','dumbbell plyo squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Step:2 Lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 As you reach the bottom of the squat, explode upward, jumping off the ground.","Step:4 While in the air, quickly switch the position of your feet, landing with your opposite foot forward.","Step:5 Immediately lower your body back into a squat position and repeat the jump, switching your feet again.","Step:6 Continue alternating the position of your feet with each jump for the desired number of repetitions."}','https://static.exercisedb.dev/media/S4pwGlc.gif','https://static.exercisedb.dev/media/S4pwGlc.gif',NULL),
('s5PdDyY','dumbbell tate press',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a flat bench with a dumbbell in each hand, palms facing each other.","Step:2 Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.","Step:3 Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.","Step:4 Rotate your wrists back to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/s5PdDyY.gif','https://static.exercisedb.dev/media/s5PdDyY.gif',NULL),
('s7HX1BY','barbell wide squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Step:2 Hold the barbell across your upper back, resting it on your traps or rear delts.","Step:3 Engage your core and keep your chest up as you lower your body down into a squat, pushing your hips back and bending your knees.","Step:4 Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/s7HX1BY.gif','https://static.exercisedb.dev/media/s7HX1BY.gif',NULL),
('S8mo30S','barbell standing front raise over head',NULL,'shoulders','delts','{"triceps","upper back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.","Step:2 Keep your back straight and engage your core.","Step:3 Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.","Step:4 Continue lifting until the barbell is slightly above shoulder level.","Step:5 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/S8mo30S.gif','https://static.exercisedb.dev/media/S8mo30S.gif',NULL),
('s8nrDXF','weighted crunch',NULL,'core','abs','{"obliques"}','other',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Hold a weight plate or dumbbell on your chest.","Step:3 Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/s8nrDXF.gif','https://static.exercisedb.dev/media/s8nrDXF.gif',NULL),
('S93zLTG','resistance band seated shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','resistance band',NULL,'{"Step:1 Sit on a chair or bench with your back straight and feet flat on the ground.","Step:2 Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Step:3 Press the band overhead, extending your arms fully.","Step:4 Pause for a moment at the top, then slowly lower the band back down to shoulder level.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/S93zLTG.gif','https://static.exercisedb.dev/media/S93zLTG.gif',NULL),
('s999Hdo','dumbbell one arm seated bicep curl on exercise ball',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Step:3 Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/s999Hdo.gif','https://static.exercisedb.dev/media/s999Hdo.gif',NULL),
('S9zHIvU','barbell rear delt row',NULL,'shoulders','delts','{"trapezius","rhomboids","biceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Bend forward at the hips, keeping your back straight and chest up.","Step:4 Pull the barbell towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/S9zHIvU.gif','https://static.exercisedb.dev/media/S9zHIvU.gif',NULL),
('Sa8mzWc','hanging pike weak',NULL,'core','abs','{"hip flexors","shoulders"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your legs up towards the bar, keeping them straight.","Step:3 Continue lifting until your body forms a 'V' shape, with your legs parallel to the ground. Emphasize weak control.","Step:4 Hold the position for a moment, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Sa8mzWc.gif','https://static.exercisedb.dev/media/Sa8mzWc.gif',NULL),
('SaDOwk7','backward jump',NULL,'legs','quads','{"hamstrings","glutes","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Bend your knees slightly and jump backwards, pushing off with both feet.","Step:3 Land softly on the balls of your feet, bending your knees to absorb the impact.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SaDOwk7.gif','https://static.exercisedb.dev/media/SaDOwk7.gif',NULL),
('Ser9eQp','lever triceps extension',NULL,'arms','triceps','{"shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the pad.","Step:2 Grasp the handles with an overhand grip and fully extend your arms in front of you.","Step:3 Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows.","Step:4 Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ser9eQp.gif','https://static.exercisedb.dev/media/Ser9eQp.gif',NULL),
('SGY8Zui','barbell clean and press',NULL,'legs','quads','{"hamstrings","glutes","shoulders","triceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and the barbell on the floor in front of you.","Step:2 Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.","Step:4 As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.","Step:5 As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.","Step:6 From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.","Step:7 Lower the barbell back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SGY8Zui.gif','https://static.exercisedb.dev/media/SGY8Zui.gif',NULL),
('SHUMp5H','dumbbell decline one arm hammer press',NULL,'arms','triceps','{"chest","shoulders"}','dumbbell',NULL,'{"Step:1 Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Step:2 Extend your arm straight up, keeping your elbow slightly bent.","Step:3 Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.","Step:4 Press the dumbbell back up to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/SHUMp5H.gif','https://static.exercisedb.dev/media/SHUMp5H.gif',NULL),
('SiWCcTN','power clean',NULL,'legs','hamstrings','{"glutes","quadriceps","calves"}','barbell',NULL,'{"Step:1 Start with the barbell on the ground in front of you, with your feet shoulder-width apart.","Step:2 Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees.","Step:4 As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.","Step:5 As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position.","Step:6 Stand up with the barbell, fully extending your hips and knees.","Step:7 Lower the barbell back down to the starting position, keeping control of the weight throughout the movement.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SiWCcTN.gif','https://static.exercisedb.dev/media/SiWCcTN.gif',NULL),
('SJAA2IQ','barbell palms up wrist curl over a bench',NULL,'arms','forearms','{"biceps","shoulders"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.","Step:2 Rest your forearms on the bench, allowing your wrists to hang off the edge.","Step:3 Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.","Step:4 Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SJAA2IQ.gif','https://static.exercisedb.dev/media/SJAA2IQ.gif',NULL),
('sJElUUI','dumbbell incline one arm press on exercise ball modified',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Step:2 Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Step:3 Hold the dumbbell at shoulder height with your palm facing forward.","Step:4 Press the dumbbell upward until your arm is fully extended.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position. Emphasize modified control.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/sJElUUI.gif','https://static.exercisedb.dev/media/sJElUUI.gif',NULL),
('sJFIDIp','biceps leg concentration curl',NULL,'arms','biceps','{"forearms"}','body weight',NULL,'{"Step:1 Sit on a bench with your legs spread apart and your feet flat on the ground.","Step:2 Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.","Step:3 With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.","Step:4 Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/sJFIDIp.gif','https://static.exercisedb.dev/media/sJFIDIp.gif',NULL),
('SJqRxOt','cable rope seated row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the rowing machine with your feet flat on the footrests and knees slightly bent.","Step:2 Grasp the cable ropes with an overhand grip, palms facing each other.","Step:3 Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Step:4 Pull the cable ropes towards your body, squeezing your shoulder blades together.","Step:5 Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SJqRxOt.gif','https://static.exercisedb.dev/media/SJqRxOt.gif',NULL),
('SKXQAx3','roller reverse crunch',NULL,'core','abs','{"hip flexors"}','other',NULL,'{"Step:1 Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.","Step:2 Place the roller between your feet and grip it with your toes.","Step:3 Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SKXQAx3.gif','https://static.exercisedb.dev/media/SKXQAx3.gif',NULL),
('slDvUAU','dumbbell hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your torso.","Step:2 Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","Step:3 This will be your starting position.","Step:4 Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:5 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:6 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:7 Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Step:8 Repeat for the recommended amount of repetitions."}','https://static.exercisedb.dev/media/slDvUAU.gif','https://static.exercisedb.dev/media/slDvUAU.gif',NULL),
('SLKj2pX','cocoons',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SLKj2pX.gif','https://static.exercisedb.dev/media/SLKj2pX.gif',NULL),
('sM84pE4','exercise ball lat stretch',NULL,'back','lats','{"shoulders","triceps"}','other',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand and extend your arm straight up overhead.","Step:3 Slowly lean to the opposite side, feeling a stretch in your lat muscle.","Step:4 Hold the stretch for 20-30 seconds, then return to the starting position.","Step:5 Repeat on the other side."}','https://static.exercisedb.dev/media/sM84pE4.gif','https://static.exercisedb.dev/media/sM84pE4.gif',NULL),
('Sn8wxAI','crunch (on stability ball, arms straight)',NULL,'core','abs','{"hip flexors"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Step:3 Place your hands behind your head or cross them over your chest.","Step:4 Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.","Step:5 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Sn8wxAI.gif','https://static.exercisedb.dev/media/Sn8wxAI.gif',NULL),
('SNFfUff','barbell lying lifting (on hip)',NULL,'legs','glutes','{"hamstrings","quadriceps"}','barbell',NULL,'{"Step:1 Lie flat on your back on a bench with your feet flat on the ground and your knees bent.","Step:2 Hold the barbell with an overhand grip and position it on your hips.","Step:3 Engaging your glutes, lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Step:4 Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SNFfUff.gif','https://static.exercisedb.dev/media/SNFfUff.gif',NULL),
('Snj1wSv','plyo push up',NULL,'chest','pectorals','{"triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart.","Step:2 Lower your chest towards the ground by bending your elbows, keeping your body in a straight line.","Step:3 Push explosively off the ground, using your chest muscles to propel your upper body off the ground.","Step:4 Land softly with your hands back in the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Snj1wSv.gif','https://static.exercisedb.dev/media/Snj1wSv.gif',NULL),
('soIB2rj','diamond push-up',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Step:2 Keep your body in a straight line from head to toe, engaging your core and glutes.","Step:3 Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/soIB2rj.gif','https://static.exercisedb.dev/media/soIB2rj.gif',NULL),
('SP3hUez','swimmer kicks v. 2 (male)',NULL,'legs','glutes','{"hamstrings","quadriceps","calves"}','body weight',NULL,'{"Step:1 Lie face down on a mat with your arms extended overhead.","Step:2 Engage your core and lift your chest and legs off the ground simultaneously.","Step:3 Kick your legs up and down in a fluttering motion, as if you were swimming.","Step:4 Continue kicking for the desired number of repetitions.","Step:5 Lower your chest and legs back down to the starting position."}','https://static.exercisedb.dev/media/SP3hUez.gif','https://static.exercisedb.dev/media/SP3hUez.gif',NULL),
('SpsOSXk','cable rear pulldown',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Adjust the cable machine so that the pulley is at the highest position.","Step:2 Sit facing the machine with your feet flat on the ground and your knees slightly bent.","Step:3 Grasp the cable attachment with an overhand grip, hands slightly wider than shoulder-width apart.","Step:4 Lean back slightly, keeping your back straight and your chest up.","Step:5 Pull the cable attachment down towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the bottom of the movement, then slowly release the cable back up to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SpsOSXk.gif','https://static.exercisedb.dev/media/SpsOSXk.gif',NULL),
('SpYC0Kp','dumbbell bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.","Step:3 Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Step:4 Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SpYC0Kp.gif','https://static.exercisedb.dev/media/SpYC0Kp.gif',NULL),
('SSsBDwB','dumbbell rear lunge',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Step:2 Take a step backward with your right foot, lowering your body into a lunge position.","Step:3 Bend your left knee and lower your body until your left thigh is parallel to the ground.","Step:4 Pause for a moment, then push through your left heel to return to the starting position.","Step:5 Repeat on the other side, stepping back with your left foot."}','https://static.exercisedb.dev/media/SSsBDwB.gif','https://static.exercisedb.dev/media/SSsBDwB.gif',NULL),
('sTfvVsG','band reverse fly',NULL,'shoulders','delts','{"upper back","trapezius"}','resistance band',NULL,'{"Step:1 Attach the band to a stationary object at chest height.","Step:2 Stand with your feet shoulder-width apart and hold the band with both hands in front of you.","Step:3 Keep your arms straight and lift them out to the sides until they are parallel to the ground.","Step:4 Squeeze your shoulder blades together at the top of the movement.","Step:5 Slowly lower your arms back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/sTfvVsG.gif','https://static.exercisedb.dev/media/sTfvVsG.gif',NULL),
('sTg7iys','band front lateral raise',NULL,'shoulders','delts','{"traps","upper back"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Step:2 Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.","Step:3 Pause for a moment at the top, then slowly lower the band back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/sTg7iys.gif','https://static.exercisedb.dev/media/sTg7iys.gif',NULL),
('sU5BrfP','leg up hamstring stretch',NULL,'legs','hamstrings','{"glutes"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended.","Step:2 Bend one knee and bring it towards your chest, holding onto your thigh or shin.","Step:3 Straighten your leg as much as possible while keeping it elevated.","Step:4 Hold the stretch for 20-30 seconds.","Step:5 Repeat with the other leg."}','https://static.exercisedb.dev/media/sU5BrfP.gif','https://static.exercisedb.dev/media/sU5BrfP.gif',NULL),
('sVQCCeG','march sit (wall)',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your back against a wall and your feet hip-width apart.","Step:2 Slowly slide your back down the wall until your knees are bent at a 90-degree angle.","Step:3 Lift your right foot off the ground and bring your knee towards your chest.","Step:4 Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest.","Step:5 Continue alternating between lifting your right and left foot for the desired number of repetitions."}','https://static.exercisedb.dev/media/sVQCCeG.gif','https://static.exercisedb.dev/media/sVQCCeG.gif',NULL),
('sVvXT5J','exercise ball pike push up',NULL,'chest','pectorals','{"shoulders","triceps","core"}','other',NULL,'{"Step:1 Start in a push-up position with your hands on the floor and your shins resting on the stability ball.","Step:2 Engage your core and lift your hips up towards the ceiling, rolling the ball towards your hands.","Step:3 Keep your legs straight and your body in a pike position, forming an inverted V shape.","Step:4 Bend your elbows and lower your upper body towards the floor, keeping your head in line with your hands.","Step:5 Push through your hands and extend your arms to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/sVvXT5J.gif','https://static.exercisedb.dev/media/sVvXT5J.gif',NULL),
('SxHteRW','dumbbell standing alternate raise',NULL,'shoulders','delts','{"traps","forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Step:2 Keep your back straight and your core engaged.","Step:3 Raise one dumbbell to the side, keeping your arm straight and your palm facing down.","Step:4 Continue lifting until your arm is parallel to the ground.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:6 Repeat with the other arm.","Step:7 Alternate between arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/SxHteRW.gif','https://static.exercisedb.dev/media/SxHteRW.gif',NULL),
('sxY5Biu','dumbbell one arm zottman preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.","Step:2 Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.","Step:3 Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","Step:4 At the top of the curl, rotate your wrist so that your palm faces up.","Step:5 Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/sxY5Biu.gif','https://static.exercisedb.dev/media/sxY5Biu.gif',NULL),
('sYCcnon','cable standing one arm triceps extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart, facing the cable machine.","Step:2 Hold the cable handle with your right hand, palm facing down, and position your arm so that it is fully extended and parallel to the ground.","Step:3 Keep your elbow stationary and close to your body.","Step:4 Slowly bend your elbow, lowering the cable handle towards the back of your head.","Step:5 Pause for a moment at the bottom of the movement, then extend your arm back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides and perform the exercise with your left arm."}','https://static.exercisedb.dev/media/sYCcnon.gif','https://static.exercisedb.dev/media/sYCcnon.gif',NULL),
('SYJ4Bkt','barbell lying preacher curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SYJ4Bkt.gif','https://static.exercisedb.dev/media/SYJ4Bkt.gif',NULL),
('syUwUKY','rotated dumbbell pronate-grip triceps extension',NULL,'arms','triceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Step:3 Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.","Step:4 Pause for a moment, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions. Focus on rotated movement."}','https://static.exercisedb.dev/media/syUwUKY.gif','https://static.exercisedb.dev/media/syUwUKY.gif',NULL),
('szIn2UK','negative crunch',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/szIn2UK.gif','https://static.exercisedb.dev/media/szIn2UK.gif',NULL),
('sZOR9EV','lever kneeling twist',NULL,'core','abs','{"obliques","lower back"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your knees resting on the pads and your upper body facing forward.","Step:2 Grasp the handles or the sides of the machine for stability.","Step:3 Keeping your core engaged, twist your torso to one side as far as comfortably possible.","Step:4 Pause for a moment, then slowly return to the starting position.","Step:5 Repeat the twist to the opposite side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/sZOR9EV.gif','https://static.exercisedb.dev/media/sZOR9EV.gif',NULL),
('SzX3uzM','barbell reverse grip bent over row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold a barbell with an overhand grip, palms facing down, and hands slightly wider than shoulder-width apart.","Step:3 Bend forward at the hips, keeping your back straight and chest up, until your torso is almost parallel to the floor.","Step:4 Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/SzX3uzM.gif','https://static.exercisedb.dev/media/SzX3uzM.gif',NULL),
('T0yTjgW','lever chest press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back flat against the pad.","Step:2 Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Step:3 Push the handles forward until your arms are fully extended, exhaling during the movement.","Step:4 Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/T0yTjgW.gif','https://static.exercisedb.dev/media/T0yTjgW.gif',NULL),
('T2fA5Ir','squat on bosu ball',NULL,'legs','quads','{"glutes","hamstrings","calves"}','other',NULL,'{"Step:1 Place the bosu ball on the ground with the flat side up.","Step:2 Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.","Step:3 Lower your body down by bending your knees and hips, as if sitting back into a chair.","Step:4 Keep your chest up and your weight on your heels.","Step:5 Lower yourself until your thighs are parallel to the ground.","Step:6 Pause for a moment, then push through your heels to return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/T2fA5Ir.gif','https://static.exercisedb.dev/media/T2fA5Ir.gif',NULL),
('T2mxWqc','chin-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Step:2 Engage your core and pull your body up towards the bar, leading with your chest.","Step:3 Continue pulling until your chin is above the bar.","Step:4 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/T2mxWqc.gif','https://static.exercisedb.dev/media/T2mxWqc.gif',NULL),
('t8iSghb','barbell lunge',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Step:2 Take a step forward with your right foot, keeping your torso upright.","Step:3 Lower your body by bending your right knee until your thigh is parallel to the ground.","Step:4 Push through your right heel to return to the starting position.","Step:5 Repeat with your left leg, alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/t8iSghb.gif','https://static.exercisedb.dev/media/t8iSghb.gif',NULL),
('T8UpLkb','mixed grip chin-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart.","Step:2 Hang from the bar with your arms fully extended and your feet off the ground.","Step:3 Engage your back muscles and pull your body up towards the bar, leading with your chest.","Step:4 Continue pulling until your chin is above the bar.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position with control.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/T8UpLkb.gif','https://static.exercisedb.dev/media/T8UpLkb.gif',NULL),
('TBNaSNs','ez barbell decline close grip face press - mini variation',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie on a decline bench with your head lower than your feet.","Step:2 Grasp the ez barbell with a close grip, palms facing each other.","Step:3 Extend your arms straight up above your chest, keeping your elbows close to your body.","Step:4 Lower the barbell towards your forehead by bending your elbows.","Step:5 Pause for a moment, then press the barbell back up to the starting position. Emphasize mini control.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/TBNaSNs.gif','https://static.exercisedb.dev/media/TBNaSNs.gif',NULL),
('tBWXbIT','cable incline fly',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Adjust the cable machine to a low position and attach the handles.","Step:2 Sit on an incline bench with your back against the pad and feet flat on the floor.","Step:3 Grasp the handles with an overhand grip and extend your arms straight out in front of you.","Step:4 Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion.","Step:5 Pause for a moment at the fully extended position, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/tBWXbIT.gif','https://static.exercisedb.dev/media/tBWXbIT.gif',NULL),
('tc5dYrf','band standing rear delt row',NULL,'shoulders','delts','{"trapezius","rhomboids","biceps"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band under your feet.","Step:2 Hold the band handles with your palms facing each other and your arms extended in front of you.","Step:3 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:4 Pull the band towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/tc5dYrf.gif','https://static.exercisedb.dev/media/tc5dYrf.gif',NULL),
('TDYiji6','jump squat v. 2',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Jump explosively, extending your hips and knees fully.","Step:4 Land softly on the balls of your feet and immediately lower your body back into a squat position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/TDYiji6.gif','https://static.exercisedb.dev/media/TDYiji6.gif',NULL),
('TFA88iB','band front raise',NULL,'shoulders','delts','{"triceps","upper back"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.","Step:2 Keep your arms straight and slowly raise them forward until they are parallel to the ground.","Step:3 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/TFA88iB.gif','https://static.exercisedb.dev/media/TFA88iB.gif',NULL),
('tFGKm99','intermediate hip flexor and quad stretch',NULL,'legs','quads','{"hamstrings","glutes"}','other',NULL,'{"Step:1 Stand upright with your feet shoulder-width apart.","Step:2 Hold onto a stable object for support.","Step:3 Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.","Step:4 Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.","Step:5 Hold the stretch for 20-30 seconds.","Step:6 Release the stretch and repeat on the left side."}','https://static.exercisedb.dev/media/tFGKm99.gif','https://static.exercisedb.dev/media/tFGKm99.gif',NULL),
('TFqbd8t','crunch floor',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engage your abs and lift your shoulders off the ground, curling forward towards your knees.","Step:4 Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/TFqbd8t.gif','https://static.exercisedb.dev/media/TFqbd8t.gif',NULL),
('tFToB7l','reverse plank with leg lift',NULL,'core','abs','{"glutes","hamstrings","shoulders"}','body weight',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.","Step:2 Press through your hands and lift your hips off the ground, coming into a reverse plank position.","Step:3 Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.","Step:4 Hold for a moment, then lower your leg back down.","Step:5 Repeat with the other leg.","Step:6 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/tFToB7l.gif','https://static.exercisedb.dev/media/tFToB7l.gif',NULL),
('tgryw5Y','push-up (on stability ball)',NULL,'chest','pectorals','{"triceps","shoulders","core"}','other',NULL,'{"Step:1 Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Step:2 Extend your legs straight out behind you, balancing on your toes.","Step:3 Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/tgryw5Y.gif','https://static.exercisedb.dev/media/tgryw5Y.gif',NULL),
('ThKP69G','cable reverse grip triceps pushdown (sz-bar) (with arm blaster)',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a straight bar to the cable machine at the highest setting.","Step:2 Stand facing the cable machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Step:5 Engage your triceps and slowly push the bar down until your arms are fully extended.","Step:6 Pause for a moment at the bottom, then slowly return the bar to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ThKP69G.gif','https://static.exercisedb.dev/media/ThKP69G.gif',NULL),
('TiaZTxx','dumbbell seated curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and a dumbbell in each hand, palms facing forward.","Step:2 Keep your back straight and your elbows close to your torso.","Step:3 Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/TiaZTxx.gif','https://static.exercisedb.dev/media/TiaZTxx.gif',NULL),
('tig3PXb','bodyweight standing close-grip row',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Bend forward at the waist, keeping your back straight and your core engaged.","Step:3 Extend your arms straight in front of you, gripping the bar or handles with a close grip.","Step:4 Pull the bar or handles towards your body, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top of the movement, then slowly release and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/tig3PXb.gif','https://static.exercisedb.dev/media/tig3PXb.gif',NULL),
('tj41Nu6','sled 45в° leg wide press',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the sled machine to a 45-degree angle.","Step:2 Sit on the sled machine with your back against the pad and your feet on the foot platform.","Step:3 Position your feet wider than shoulder-width apart.","Step:4 Push against the foot platform to extend your legs and straighten your knees.","Step:5 Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/tj41Nu6.gif','https://static.exercisedb.dev/media/tj41Nu6.gif',NULL),
('tJ5nYqo','ez-bar biceps curl (with arm blaster)',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Step:2 Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.","Step:3 Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the barbell back to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/tJ5nYqo.gif','https://static.exercisedb.dev/media/tJ5nYqo.gif',NULL),
('tnaj0mT','swing 360',NULL,'cardio','cardiovascular system','{"shoulders","core"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold your arms straight out in front of you, parallel to the ground.","Step:3 Engage your core and swing your arms in a circular motion, rotating your torso as you do so.","Step:4 Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions.","Step:5 Remember to breathe throughout the exercise."}','https://static.exercisedb.dev/media/tnaj0mT.gif','https://static.exercisedb.dev/media/tnaj0mT.gif',NULL),
('Tq6gbK6','cable straight back seated row',NULL,'back','upper back','{"biceps","forearms","shoulders"}','cable',NULL,'{"Step:1 Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Step:2 Grasp the cable handles with an overhand grip, palms facing down.","Step:3 Keep your back straight and lean slightly forward from the hips.","Step:4 Pull the cable handles towards your body, squeezing your shoulder blades together.","Step:5 Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Tq6gbK6.gif','https://static.exercisedb.dev/media/Tq6gbK6.gif',NULL),
('trmte8s','band shrug',NULL,'other','traps','{"shoulders"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band under your feet, holding the ends with your hands.","Step:2 Keep your arms straight and relaxed, and let the band hang in front of your thighs.","Step:3 Engage your traps by shrugging your shoulders upward, lifting the band as high as possible.","Step:4 Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/trmte8s.gif','https://static.exercisedb.dev/media/trmte8s.gif',NULL),
('trqKQv2','smith bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the height of the smith machine bar to chest level.","Step:2 Lie flat on the bench with your feet firmly planted on the ground.","Step:3 Grip the bar with an overhand grip slightly wider than shoulder-width apart.","Step:4 Unrack the bar and lower it towards your chest, keeping your elbows tucked in.","Step:5 Pause for a moment when the bar touches your chest.","Step:6 Push the bar back up to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/trqKQv2.gif','https://static.exercisedb.dev/media/trqKQv2.gif',NULL),
('tTuZSDT','lever one arm lateral wide pulldown',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Step:2 Grasp the handle with an overhand grip and fully extend your arm, keeping a slight bend in your elbow.","Step:3 Pull the handle down and across your body towards your opposite hip, squeezing your lat muscle at the bottom of the movement.","Step:4 Slowly return the handle to the starting position, fully extending your arm.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/tTuZSDT.gif','https://static.exercisedb.dev/media/tTuZSDT.gif',NULL),
('tuIZFDt','intermediate style kneeling plank tap shoulder (male)',NULL,'core','abs','{"shoulders","triceps"}','body weight',NULL,'{"Step:1 Start in a kneeling position with your hands on the ground, shoulder-width apart.","Step:2 Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Step:3 (intermediate variation) Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Step:4 Return the hand to the ground and repeat with the other hand.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/tuIZFDt.gif','https://static.exercisedb.dev/media/tuIZFDt.gif',NULL),
('TUZLh71','band squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart, with the band placed just above your knees.","Step:2 Keeping your chest up and core engaged, push your hips back and bend your knees to lower into a squat position.","Step:3 Make sure your knees are tracking over your toes and your weight is in your heels.","Step:4 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/TUZLh71.gif','https://static.exercisedb.dev/media/TUZLh71.gif',NULL),
('TV87DNB','inchworm v. 2',NULL,'core','abs','{"shoulders","hamstrings"}','body weight',NULL,'{"Step:1 Start in a standing position with your feet hip-width apart.","Step:2 Bend forward at the waist and place your hands on the ground in front of you.","Step:3 Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Step:4 Keeping your legs straight, walk your feet towards your hands, bringing your hips up towards the ceiling.","Step:5 Continue walking your hands forward, repeating the movement for the desired number of repetitions."}','https://static.exercisedb.dev/media/TV87DNB.gif','https://static.exercisedb.dev/media/TV87DNB.gif',NULL),
('TVdivgY','dumbbell incline alternate press',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Step:2 Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.","Step:3 Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.","Step:4 Push the dumbbells up with your chest and shoulders, extending your arms fully.","Step:5 Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.","Step:6 Repeat for the desired number of repetitions, alternating arms."}','https://static.exercisedb.dev/media/TVdivgY.gif','https://static.exercisedb.dev/media/TVdivgY.gif',NULL),
('TXtXc84','cable tuck reverse crunch',NULL,'core','abs','{"hip flexors"}','cable',NULL,'{"Step:1 Attach a cable to a low pulley and lie down on a mat facing up.","Step:2 Hold the cable with both hands and extend your arms straight up above your chest.","Step:3 Bend your knees and lift your legs up, bringing your knees towards your chest.","Step:4 At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.","Step:5 Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/TXtXc84.gif','https://static.exercisedb.dev/media/TXtXc84.gif',NULL),
('tZkGYZ9','band bicycle crunch',NULL,'core','abs','{"hip flexors","obliques"}','resistance band',NULL,'{"Step:1 Lie flat on your back with your hands behind your head and your knees bent.","Step:2 Lift your feet off the ground and bring your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.","Step:3 Straighten your right leg while bringing your left knee towards your chest and twisting your torso to bring your right elbow towards your left knee.","Step:4 Continue alternating the twisting motion, as if you are pedaling a bicycle, while keeping your core engaged throughout the movement.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/tZkGYZ9.gif','https://static.exercisedb.dev/media/tZkGYZ9.gif',NULL),
('tznL2Ad','kettlebell double jerk',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Step:2 Bend your knees slightly and engage your core.","Step:3 Press the kettlebells overhead, fully extending your arms.","Step:4 Bend your knees and quickly drop into a partial squat.","Step:5 Explosively extend your hips and knees, driving the kettlebells overhead.","Step:6 Lock out your arms and catch the kettlebells overhead with your knees slightly bent.","Step:7 Stand up straight and return to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/tznL2Ad.gif','https://static.exercisedb.dev/media/tznL2Ad.gif',NULL),
('u0cNiij','low glute bridge on floor',NULL,'legs','glutes','{"hamstrings","core"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your arms by your sides, palms facing down.","Step:3 Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Step:4 Pause for a moment at the top, squeezing your glutes.","Step:5 Slowly lower your hips back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/u0cNiij.gif','https://static.exercisedb.dev/media/u0cNiij.gif',NULL),
('u0pLNgz','sled one leg calf press on leg press',NULL,'legs','calves','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Step:2 Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.","Step:3 Place your toes and the balls of your feet on the sled, keeping your heels off.","Step:4 Push the sled forward by extending your ankles, keeping your knees slightly bent.","Step:5 Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/u0pLNgz.gif','https://static.exercisedb.dev/media/u0pLNgz.gif',NULL),
('u1iHcoD','prone dumbbell upright shoulder external rotation',NULL,'shoulders','delts','{"rotator cuff","trapezius"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Step:2 Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent. Emphasize prone control.","Step:3 Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/u1iHcoD.gif','https://static.exercisedb.dev/media/u1iHcoD.gif',NULL),
('u27Kcdz','bench hip extension',NULL,'legs','glutes','{"hamstrings"}','body weight',NULL,'{"Step:1 Sit on a bench with your back against the bench and your feet flat on the ground.","Step:2 Place your hands on the bench for support.","Step:3 Engage your glutes and hamstrings, then lift your hips off the bench until your body forms a straight line from your knees to your shoulders.","Step:4 Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/u27Kcdz.gif','https://static.exercisedb.dev/media/u27Kcdz.gif',NULL),
('u2X71Np','cable front raise',NULL,'shoulders','delts','{"triceps","forearms"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Step:2 Keep your back straight and your core engaged.","Step:3 Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Step:4 Continue lifting until your arms are parallel to the floor.","Step:5 Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/u2X71Np.gif','https://static.exercisedb.dev/media/u2X71Np.gif',NULL),
('U3ffHlY','cable rope lying on floor tricep extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Attach a rope to a cable machine and set it to the lowest position.","Step:2 Lie on the floor facing up, with your head towards the cable machine.","Step:3 Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.","Step:4 Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.","Step:5 Pause for a moment, then extend your arms back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/U3ffHlY.gif','https://static.exercisedb.dev/media/U3ffHlY.gif',NULL),
('u3UuCZu','intense kettlebell two arm row',NULL,'back','upper back','{"biceps","forearms"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Step:2 Bend forward at the hips, keeping your back straight and your core engaged.","Step:3 Pull the kettlebells up towards your chest, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.","Step:5 Repeat for the desired number of repetitions. Maintain intense form throughout."}','https://static.exercisedb.dev/media/u3UuCZu.gif','https://static.exercisedb.dev/media/u3UuCZu.gif',NULL),
('u4bAmKp','band twisting overhead press',NULL,'shoulders','delts','{"triceps","upper back"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band under your feet.","Step:2 Hold the band handles at shoulder height with your palms facing forward.","Step:3 Engage your core and press the band overhead, fully extending your arms.","Step:4 As you press, twist your torso to one side, keeping your hips stable.","Step:5 Pause for a moment at the top, then return to the starting position.","Step:6 Repeat the press and twist on the opposite side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/u4bAmKp.gif','https://static.exercisedb.dev/media/u4bAmKp.gif',NULL),
('u5ESqzH','donkey calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand with your toes on an elevated surface, such as a step or block.","Step:2 Place your hands on a stable support, such as a wall or railing, for balance.","Step:3 Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Step:4 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/u5ESqzH.gif','https://static.exercisedb.dev/media/u5ESqzH.gif',NULL),
('U5INZY6','cable one arm pulldown',NULL,'back','lats','{"biceps","forearms"}','cable',NULL,'{"Step:1 Attach a single handle to a high pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the handle with an overhand grip and extend your arm fully.","Step:4 Keep your back straight and your core engaged.","Step:5 Pull the handle down towards your side while keeping your elbow close to your body.","Step:6 Pause for a moment at the bottom of the movement, squeezing your lat muscle.","Step:7 Slowly release the handle back to the starting position.","Step:8 Repeat for the desired number of repetitions.","Step:9 Switch sides and repeat the exercise with the other arm."}','https://static.exercisedb.dev/media/U5INZY6.gif','https://static.exercisedb.dev/media/U5INZY6.gif',NULL),
('U6G2gk9','body-up',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.","Step:2 Extend your legs out in front of you, keeping your heels on the ground and your body straight.","Step:3 Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.","Step:4 Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/U6G2gk9.gif','https://static.exercisedb.dev/media/U6G2gk9.gif',NULL),
('U7D9Fx3','dumbbell incline two arm extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Step:2 Slowly lie back on the bench, keeping the dumbbells close to your chest.","Step:3 Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/U7D9Fx3.gif','https://static.exercisedb.dev/media/U7D9Fx3.gif',NULL),
('UDlhcO8','barbell upright row',NULL,'shoulders','delts','{"traps","biceps"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:2 Let the barbell hang in front of your thighs, arms fully extended.","Step:3 Keeping your back straight and core engaged, exhale and lift the barbell straight up towards your chin, leading with your elbows.","Step:4 Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UDlhcO8.gif','https://static.exercisedb.dev/media/UDlhcO8.gif',NULL),
('UDm6cGl','kettlebell seesaw press',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Step:2 Press one kettlebell overhead while keeping the other kettlebell at shoulder height.","Step:3 Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.","Step:4 Continue alternating the pressing motion, creating a seesaw-like movement.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UDm6cGl.gif','https://static.exercisedb.dev/media/UDm6cGl.gif',NULL),
('UEjSrKI','cable seated twist',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Sit on a cable machine with your feet flat on the ground and your knees slightly bent.","Step:2 Hold the cable handle with both hands and extend your arms straight in front of you.","Step:3 Keeping your core engaged, slowly rotate your torso to one side, pulling the cable across your body.","Step:4 Pause for a moment at the end of the range of motion, then slowly rotate back to the starting position.","Step:5 Repeat on the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/UEjSrKI.gif','https://static.exercisedb.dev/media/UEjSrKI.gif',NULL),
('ufaxB52','band close-grip push-up',NULL,'arms','triceps','{"chest","shoulders"}','resistance band',NULL,'{"Step:1 Place a band around your upper arms, just above the elbows.","Step:2 Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.","Step:3 Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.","Step:4 Push through your palms to extend your arms and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ufaxB52.gif','https://static.exercisedb.dev/media/ufaxB52.gif',NULL),
('UfePqpx','smith deadlift',NULL,'legs','glutes','{"hamstrings","quadriceps","lower back"}','machine',NULL,'{"Step:1 Set up the smith machine with the bar at hip height.","Step:2 Stand with your feet shoulder-width apart, toes pointing slightly outward.","Step:3 Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.","Step:4 Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.","Step:5 Stand up straight, fully extending your hips and knees.","Step:6 Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UfePqpx.gif','https://static.exercisedb.dev/media/UfePqpx.gif',NULL),
('UFGF6gk','cable rope crossover seated row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the rowing machine with your feet flat on the footrests and your knees slightly bent.","Step:2 Grasp the cable ropes with an overhand grip, palms facing each other.","Step:3 Lean back slightly, keeping your back straight and your core engaged.","Step:4 Pull the cable ropes towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UFGF6gk.gif','https://static.exercisedb.dev/media/UFGF6gk.gif',NULL),
('UgDm3oy','kneeling jump squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Start by kneeling on the ground with your feet hip-width apart and your toes pointing forward.","Step:2 Hold a barbell across your upper back, resting it on your shoulders.","Step:3 Engage your core and glutes, then explosively jump up into the air, extending your hips and knees.","Step:4 As you jump, push through your toes and fully extend your ankles, knees, and hips.","Step:5 Land softly back on the ground, bending your knees to absorb the impact.","Step:6 Immediately go into the next repetition, repeating the jump squat motion."}','https://static.exercisedb.dev/media/UgDm3oy.gif','https://static.exercisedb.dev/media/UgDm3oy.gif',NULL),
('UGhRD1A','assisted lying leg raise with lateral throw down',NULL,'core','abs','{"hip flexors","obliques"}','other',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms by your sides.","Step:2 Place your hands under your glutes for support.","Step:3 Engage your abs and lift your legs off the ground, keeping them straight.","Step:4 While keeping your legs together, lower them to one side until they are a few inches above the ground.","Step:5 Pause for a moment, then lift your legs back to the starting position.","Step:6 Repeat the movement to the other side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/UGhRD1A.gif','https://static.exercisedb.dev/media/UGhRD1A.gif',NULL),
('UHJlbu3','kettlebell swing',NULL,'legs','glutes','{"hamstrings","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes pointed slightly outward.","Step:2 Hold the kettlebell with both hands in front of your body, arms extended.","Step:3 Bend your knees slightly and hinge at the hips, pushing your butt back.","Step:4 Swing the kettlebell back between your legs, keeping your arms straight and maintaining a flat back.","Step:5 Drive your hips forward and swing the kettlebell up to shoulder height, using the momentum generated by your hips.","Step:6 Allow the kettlebell to swing back down between your legs and repeat the movement for the desired number of repetitions."}','https://static.exercisedb.dev/media/UHJlbu3.gif','https://static.exercisedb.dev/media/UHJlbu3.gif',NULL),
('UI81amT','supine style band alternating v-up',NULL,'core','abs','{"hip flexors"}','resistance band',NULL,'{"Step:1 Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Step:2 Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Step:3 As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other. Focus on supine movement.","Step:4 Repeat the movement, alternating the position of your legs with each repetition.","Step:5 Continue for the desired number of repetitions."}','https://static.exercisedb.dev/media/UI81amT.gif','https://static.exercisedb.dev/media/UI81amT.gif',NULL),
('UIbGx6H','dumbbell reverse bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your knees bent.","Step:2 Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.","Step:3 Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.","Step:4 Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.","Step:5 Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UIbGx6H.gif','https://static.exercisedb.dev/media/UIbGx6H.gif',NULL),
('UilDHSs','dumbbell standing palms in press',NULL,'shoulders','delts','{"triceps","chest"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.","Step:2 Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.","Step:3 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UilDHSs.gif','https://static.exercisedb.dev/media/UilDHSs.gif',NULL),
('uJmK7Z1','dumbbell seated neutral wrist curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.","Step:2 Rest your forearms on your thighs, allowing the dumbbells to hang down.","Step:3 Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/uJmK7Z1.gif','https://static.exercisedb.dev/media/uJmK7Z1.gif',NULL),
('UKWTJWR','cable standing up straight crossovers',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Stand in the middle of a cable machine with your feet shoulder-width apart.","Step:2 Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.","Step:3 Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.","Step:4 Pause for a moment, then slowly return to the starting position, keeping your arms extended.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UKWTJWR.gif','https://static.exercisedb.dev/media/UKWTJWR.gif',NULL),
('uKyN64F','barbell one leg squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell across your upper back.","Step:2 Lift one foot off the ground and extend it forward, keeping it parallel to the ground.","Step:3 Bend your standing leg and lower your body down as if sitting back into a chair, keeping your chest up and your back straight.","Step:4 Lower yourself until your thigh is parallel to the ground, then push through your heel to return to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch legs and repeat."}','https://static.exercisedb.dev/media/uKyN64F.gif','https://static.exercisedb.dev/media/uKyN64F.gif',NULL),
('Ul5OFSV','resistance band leg extension declined',NULL,'legs','quads','{"hamstrings"}','resistance band',NULL,'{"Step:1 Attach the resistance band to a sturdy anchor point and secure it around your ankle.","Step:2 Stand facing the anchor point with your feet shoulder-width apart.","Step:3 Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.","Step:4 Pause for a moment at the top, then slowly return your leg to the starting position. Focus on declined movement.","Step:5 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/Ul5OFSV.gif','https://static.exercisedb.dev/media/Ul5OFSV.gif',NULL),
('uL9CsKm','ankle circles',NULL,'legs','calves','{"ankle stabilizers"}','body weight',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you.","Step:2 Lift one leg off the ground and rotate your ankle in a circular motion.","Step:3 Perform the desired number of circles in one direction, then switch to the other direction.","Step:4 Repeat with the other leg."}','https://static.exercisedb.dev/media/uL9CsKm.gif','https://static.exercisedb.dev/media/uL9CsKm.gif',NULL),
('UM8mgyG','kettlebell arnold press',NULL,'shoulders','delts','{"triceps","upper back"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.","Step:2 Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.","Step:3 Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UM8mgyG.gif','https://static.exercisedb.dev/media/UM8mgyG.gif',NULL),
('Um8xUAc','barbell prone incline curl with intensive',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Lie face down on the bench with your chest and stomach resting against it.","Step:3 Hold a barbell with an underhand grip, shoulder-width apart.","Step:4 Extend your arms fully, allowing the barbell to hang down towards the floor.","Step:5 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:6 Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Step:7 (intensive variation) Hold the contracted position for a brief pause as you squeeze your biceps.","Step:8 Inhale and slowly begin to lower the barbell back to the starting position.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Um8xUAc.gif','https://static.exercisedb.dev/media/Um8xUAc.gif',NULL),
('UmpPAAe','dumbbell standing kickback',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Extend your arms straight back, squeezing your triceps at the top of the movement.","Step:4 Pause for a moment, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UmpPAAe.gif','https://static.exercisedb.dev/media/UmpPAAe.gif',NULL),
('UNAB8ak','band one arm overhead biceps curl',NULL,'arms','biceps','{"forearms","shoulders"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place one end of the band under your foot.","Step:2 Hold the other end of the band with your arm fully extended overhead, palm facing forward.","Step:3 Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.","Step:4 Pause for a moment at the top, then slowly lower your forearm back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/UNAB8ak.gif','https://static.exercisedb.dev/media/UNAB8ak.gif',NULL),
('UOphC6N','cable side bend smooth',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart and grasp the cable handle with one hand.","Step:2 Keep your back straight and your core engaged.","Step:3 Slowly bend sideways at the waist, lowering the cable handle towards your knee.","Step:4 Pause for a moment, then return to the starting position. Focus on smooth movement.","Step:5 Repeat on the other side.","Step:6 Alternate sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/UOphC6N.gif','https://static.exercisedb.dev/media/UOphC6N.gif',NULL),
('uOV3Itw','triceps stretch',NULL,'arms','triceps','{"shoulders"}','body weight',NULL,'{"Step:1 Stand or sit upright with your back straight.","Step:2 Extend one arm overhead, bending it at the elbow.","Step:3 Place your opposite hand on the bent elbow and gently pull it towards your head.","Step:4 Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.","Step:5 Release the stretch and repeat on the other arm."}','https://static.exercisedb.dev/media/uOV3Itw.gif','https://static.exercisedb.dev/media/uOV3Itw.gif',NULL),
('UoX77uR','dumbbell seated one leg calf raise - hammer grip deep',NULL,'legs','calves','{"hamstrings","glutes"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.","Step:2 Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.","Step:3 Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.","Step:4 Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.","Step:5 Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Step:6 (deep variation) Repeat for the desired number of repetitions, then switch to the other leg."}','https://static.exercisedb.dev/media/UoX77uR.gif','https://static.exercisedb.dev/media/UoX77uR.gif',NULL),
('UpAlold','rear decline bridge',NULL,'legs','glutes','{"hamstrings","lower back"}','body weight',NULL,'{"Step:1 Lie on your back with your feet flat on the ground and your knees bent.","Step:2 Place your arms by your sides with your palms facing down.","Step:3 Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders.","Step:4 Hold this position for a few seconds, then slowly lower your hips back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UpAlold.gif','https://static.exercisedb.dev/media/UpAlold.gif',NULL),
('UpWmA5E','l-sit on floor',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Sit on the floor with your legs extended in front of you.","Step:2 Place your hands on the floor beside your hips, fingers pointing forward.","Step:3 Engage your core and lift your legs off the ground, keeping them straight.","Step:4 Try to bring your legs parallel to the floor, forming an 'L' shape with your body.","Step:5 Hold this position for as long as you can.","Step:6 Slowly lower your legs back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UpWmA5E.gif','https://static.exercisedb.dev/media/UpWmA5E.gif',NULL),
('UQr48Oi','pull-in (on stability ball)',NULL,'core','abs','{"hip flexors"}','other',NULL,'{"Step:1 Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Place your hands on the sides of the stability ball for support.","Step:3 Engage your abs and slowly roll your hips forward, bringing your knees towards your chest.","Step:4 Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UQr48Oi.gif','https://static.exercisedb.dev/media/UQr48Oi.gif',NULL),
('uSkDMYl','dumbbell bicep curl with stork stance',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Step:2 Extend one leg behind you, balancing on the toes of that foot.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch legs and repeat."}','https://static.exercisedb.dev/media/uSkDMYl.gif','https://static.exercisedb.dev/media/uSkDMYl.gif',NULL),
('uTBt1HV','scapular pull-up',NULL,'back','traps','{"biceps","rhomboids","rear deltoids"}','body weight',NULL,'{"Step:1 Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Step:2 Retract your shoulder blades by pulling them down and back.","Step:3 Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.","Step:4 Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/uTBt1HV.gif','https://static.exercisedb.dev/media/uTBt1HV.gif',NULL),
('UtmIqcI','side wrist pull stretch',NULL,'arms','forearms','{"wrists","hands"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your arms extended in front of you.","Step:2 Extend your right arm out to the side, parallel to the ground, with your palm facing down.","Step:3 With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.","Step:4 Hold the stretch for 15-30 seconds, then release.","Step:5 Repeat on the other side."}','https://static.exercisedb.dev/media/UtmIqcI.gif','https://static.exercisedb.dev/media/UtmIqcI.gif',NULL),
('Uto7l43','chest and front of shoulder stretch',NULL,'chest','pectorals','{"deltoids"}','body weight',NULL,'{"Step:1 Stand tall with your feet shoulder-width apart.","Step:2 Extend your arms straight out in front of you at shoulder height.","Step:3 Cross your arms in front of your body, with your right arm on top of your left arm.","Step:4 Interlace your fingers and press your palms together.","Step:5 Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.","Step:6 Hold the stretch for 20-30 seconds, then release.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Uto7l43.gif','https://static.exercisedb.dev/media/Uto7l43.gif',NULL),
('uTv34oq','bodyweight standing row (with towel)',NULL,'back','upper back','{"biceps","shoulders"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a towel in front of you with both hands.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Pull the towel towards your chest, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top, then slowly release the tension and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/uTv34oq.gif','https://static.exercisedb.dev/media/uTv34oq.gif',NULL),
('UVL20oz','otis up',NULL,'core','abs','{"hip flexors","lower back"}','other',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UVL20oz.gif','https://static.exercisedb.dev/media/UVL20oz.gif',NULL),
('UVo2Qs2','flutter kicks',NULL,'legs','glutes','{"hip flexors","lower abs"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and your hands by your sides.","Step:2 Engage your core and lift your legs off the ground about 6 inches.","Step:3 Keeping your legs straight, alternate lifting one leg slightly higher than the other.","Step:4 Continue this fluttering motion for the desired number of repetitions."}','https://static.exercisedb.dev/media/UVo2Qs2.gif','https://static.exercisedb.dev/media/UVo2Qs2.gif',NULL),
('uWpxD4v','arm slingers hanging bent knee legs',NULL,'core','abs','{"shoulders","back"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your knees bent at a 90-degree angle.","Step:2 Engage your core and lift your knees towards your chest, bringing them as close to your elbows as possible.","Step:3 Slowly lower your legs back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/uWpxD4v.gif','https://static.exercisedb.dev/media/uWpxD4v.gif',NULL),
('uX3sUBz','inverted row v. 2',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Set up a bar at waist height on a Smith machine or use a suspension trainer.","Step:2 Stand facing the bar or suspension trainer and grab it with an overhand grip, hands shoulder-width apart.","Step:3 Walk your feet forward, leaning back until your body is at a slight angle.","Step:4 Keep your body straight and pull your chest up towards the bar or handles, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/uX3sUBz.gif','https://static.exercisedb.dev/media/uX3sUBz.gif',NULL),
('uxJcFUU','cable lying triceps extension v. 2',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Attach a rope handle to a low pulley cable machine.","Step:2 Lie down on a flat bench facing up, with your head towards the cable machine.","Step:3 Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.","Step:4 Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.","Step:5 Pause for a moment at the bottom, then extend your arms back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/uxJcFUU.gif','https://static.exercisedb.dev/media/uxJcFUU.gif',NULL),
('UXpKJoq','lever lying two-one leg curl',NULL,'legs','hamstrings','{"glutes"}','machine',NULL,'{"Step:1 Adjust the machine to fit your body and sit on it with your back against the backrest.","Step:2 Place your legs on the lever pad, just above your ankles.","Step:3 Grasp the handles on the sides of the machine for support.","Step:4 Keeping your upper body still, exhale and curl your legs up towards your glutes.","Step:5 Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UXpKJoq.gif','https://static.exercisedb.dev/media/UXpKJoq.gif',NULL),
('Uywa4S5','dumbbell lunge with firm',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Step:2 Take a step forward with your right foot, lowering your body into a lunge position.","Step:3 Keep your back straight and your chest up as you lower your body. Maintain firm form throughout.","Step:4 Push through your right heel to return to the starting position.","Step:5 Repeat with your left leg.","Step:6 Alternate legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/Uywa4S5.gif','https://static.exercisedb.dev/media/Uywa4S5.gif',NULL),
('UzkLrem','dumbbell rear lateral raise (support head)',NULL,'shoulders','delts','{"traps","rhomboids"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/UzkLrem.gif','https://static.exercisedb.dev/media/UzkLrem.gif',NULL),
('uZKq7lo','forward jump',NULL,'legs','quads','{"calves","hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Bend your knees and lower your body into a squat position.","Step:3 Swing your arms back for momentum.","Step:4 Jump forward explosively, extending your hips, knees, and ankles.","Step:5 Land softly on the balls of your feet and immediately go into the next jump.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/uZKq7lo.gif','https://static.exercisedb.dev/media/uZKq7lo.gif',NULL),
('V07qpXy','lever alternate leg press',NULL,'legs','quads','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the seat and foot platform of the leverage machine to your desired position.","Step:2 Sit on the machine with your back against the backrest and your feet on the foot platform.","Step:3 Place your hands on the handles or sides of the machine for stability.","Step:4 Push one foot against the foot platform, extending your leg until it is almost fully straight.","Step:5 Pause for a moment, then slowly bend your leg and return to the starting position.","Step:6 Repeat with the other leg.","Step:7 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/V07qpXy.gif','https://static.exercisedb.dev/media/V07qpXy.gif',NULL),
('v1qBec9','dumbbell rear lateral raise',NULL,'shoulders','delts','{"traps","rhomboids"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.","Step:3 Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/v1qBec9.gif','https://static.exercisedb.dev/media/v1qBec9.gif',NULL),
('v2DfH14','bodyweight standing close-grip one arm row',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.","Step:2 Bend forward at the hips, keeping your back straight and your core engaged.","Step:3 Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/v2DfH14.gif','https://static.exercisedb.dev/media/v2DfH14.gif',NULL),
('v3vLFW0','close-grip push-up (on knees)',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Step:2 Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.","Step:3 Pause for a moment when your chest is just above the ground.","Step:4 Push through your palms to straighten your arms and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/v3vLFW0.gif','https://static.exercisedb.dev/media/v3vLFW0.gif',NULL),
('v3xmPAR','lever seated fly',NULL,'chest','pectorals','{"deltoids","trapezius"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the pad.","Step:2 Grasp the handles with a pronated grip and keep your elbows slightly bent.","Step:3 Exhale and push the handles forward, bringing them together in front of your chest.","Step:4 Pause for a moment, squeezing your chest muscles.","Step:5 Inhale and slowly return to the starting position, allowing your chest muscles to stretch.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/v3xmPAR.gif','https://static.exercisedb.dev/media/v3xmPAR.gif',NULL),
('V4ryaZa','ez barbell close-grip curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.","Step:2 Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Step:3 Curl the barbell up towards your shoulders, contracting your biceps.","Step:4 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/V4ryaZa.gif','https://static.exercisedb.dev/media/V4ryaZa.gif',NULL),
('v6EKk0O','half knee bends (male) with blunt',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Bend your knees and lower your body down as if you were sitting back into a chair. Emphasize blunt control.","Step:3 Keep your chest up and your weight in your heels.","Step:4 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/v6EKk0O.gif','https://static.exercisedb.dev/media/v6EKk0O.gif',NULL),
('v7p5bYl','kick out sit',NULL,'legs','hamstrings','{"quadriceps","glutes"}','body weight',NULL,'{"Step:1 Sit on the edge of a bench or chair with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Lean back slightly and place your hands on the edge of the bench or chair for support.","Step:3 Engaging your hamstrings, lift your feet off the ground and extend your legs straight out in front of you.","Step:4 Pause for a moment at the top, then slowly bend your knees and bring your feet back towards your body.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/v7p5bYl.gif','https://static.exercisedb.dev/media/v7p5bYl.gif',NULL),
('V7rWsT5','lever military press with strength',NULL,'shoulders','delts','{"triceps","upper chest"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the backrest.","Step:2 Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Step:3 Push the handles upward until your arms are fully extended, but do not lock your elbows.","Step:4 (strength variation) Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/V7rWsT5.gif','https://static.exercisedb.dev/media/V7rWsT5.gif',NULL),
('VaP75jl','barbell rear lunge',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and a barbell resting on your upper back.","Step:2 Take a step backward with your right foot, landing on the ball of your foot.","Step:3 Bend both knees to lower your body until your left thigh is parallel to the ground.","Step:4 Push through your left heel to return to the starting position.","Step:5 Repeat with the other leg."}','https://static.exercisedb.dev/media/VaP75jl.gif','https://static.exercisedb.dev/media/VaP75jl.gif',NULL),
('vAwm6rK','cable press on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','cable',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.","Step:2 Hold the cable handles at chest height with your palms facing down and your elbows bent.","Step:3 Engage your core and press the cable handles forward until your arms are fully extended.","Step:4 Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vAwm6rK.gif','https://static.exercisedb.dev/media/vAwm6rK.gif',NULL),
('VBAWRPG','weighted front plank',NULL,'core','abs','{"shoulders","lower back"}','other',NULL,'{"Step:1 Start by lying face down on the floor.","Step:2 Place your forearms on the ground, with your elbows directly under your shoulders.","Step:3 Extend your legs straight out behind you, with your toes on the ground.","Step:4 Engage your core and lift your body off the ground, balancing on your forearms and toes.","Step:5 Keep your body in a straight line from your head to your heels.","Step:6 Hold this position for the desired amount of time.","Step:7 Lower your body back down to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VBAWRPG.gif','https://static.exercisedb.dev/media/VBAWRPG.gif',NULL),
('vBNyir7','ez barbell reverse grip preacher curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a preacher bench with your chest against the pad and your feet flat on the floor.","Step:2 Grasp the ez barbell with an underhand grip, hands shoulder-width apart.","Step:3 Rest your upper arms on the pad, allowing your forearms to hang down.","Step:4 Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Step:5 Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vBNyir7.gif','https://static.exercisedb.dev/media/vBNyir7.gif',NULL),
('VdLZ3nB','dumbbell one arm reverse spider curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.","Step:2 Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.","Step:3 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:4 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/VdLZ3nB.gif','https://static.exercisedb.dev/media/VdLZ3nB.gif',NULL),
('VEcJRo2','hanging leg hip raise',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.","Step:3 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VEcJRo2.gif','https://static.exercisedb.dev/media/VEcJRo2.gif',NULL),
('VedGSby','assisted prone hamstring',NULL,'legs','hamstrings','{"glutes","lower back"}','other',NULL,'{"Step:1 Lie face down on a mat or bench with your legs fully extended.","Step:2 Have a partner or use a resistance band to secure your ankles.","Step:3 Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VedGSby.gif','https://static.exercisedb.dev/media/VedGSby.gif',NULL),
('veXwo0D','cable floor seated wide-grip row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the floor with your legs extended and your back straight.","Step:2 Attach a cable handle to a low pulley and position the cable machine behind you.","Step:3 Grasp the handle with a wide overhand grip, palms facing down.","Step:4 Lean back slightly, keeping your back straight and your chest lifted.","Step:5 Pull the handle towards your waist, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement, then slowly release the handle back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/veXwo0D.gif','https://static.exercisedb.dev/media/veXwo0D.gif',NULL),
('Vh0GsK4','cable incline bench press',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Adjust the bench to a 45-degree incline.","Step:2 Attach the cable handles to the high pulleys.","Step:3 Sit on the bench facing the cable machine with your feet flat on the ground.","Step:4 Grasp the handles with an overhand grip and bring them to shoulder height.","Step:5 Push the handles forward and upward until your arms are fully extended.","Step:6 Pause for a moment, then slowly lower the handles back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Vh0GsK4.gif','https://static.exercisedb.dev/media/Vh0GsK4.gif',NULL),
('VhX2JdE','cable standing back wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','cable',NULL,'{"Step:1 Stand facing a cable machine with your feet shoulder-width apart.","Step:2 Hold the cable handle with an overhand grip, palms facing down.","Step:3 Keep your arms straight and your elbows close to your sides.","Step:4 Slowly curl your wrists upward, bringing the cable handle towards your body.","Step:5 Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VhX2JdE.gif','https://static.exercisedb.dev/media/VhX2JdE.gif',NULL),
('vi8EhoE','dumbbell around pullover',NULL,'chest','pectorals','{"triceps","latissimus dorsi"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your head at one end and your feet firmly on the ground.","Step:2 Hold a dumbbell with both hands and extend your arms straight above your chest.","Step:3 Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.","Step:4 Pause for a moment at the bottom, then raise the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vi8EhoE.gif','https://static.exercisedb.dev/media/vi8EhoE.gif',NULL),
('vIICElP','band lying hip internal rotation',NULL,'legs','glutes','{"hamstrings","quadriceps"}','resistance band',NULL,'{"Step:1 Lie on your back with your legs straight and a resistance band looped around your feet.","Step:2 Bend your knees and bring them towards your chest, keeping your feet together.","Step:3 Slowly rotate your knees outwards, away from each other, while keeping your feet together.","Step:4 Pause for a moment at the end of the rotation, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vIICElP.gif','https://static.exercisedb.dev/media/vIICElP.gif',NULL),
('VjYliFZ','cable reverse-grip pushdown',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a straight bar to a high pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Step:5 Using your triceps, push the bar down until your arms are fully extended and your triceps are contracted.","Step:6 Pause for a moment, then slowly return the bar to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VjYliFZ.gif','https://static.exercisedb.dev/media/VjYliFZ.gif',NULL),
('vKilzz3','dumbbell standing inner biceps curl v. 2',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your torso.","Step:2 Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","Step:3 While holding your upper arms stationary, curl the weights while contracting your biceps.","Step:4 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Slowly begin to bring the dumbbells back to the starting position as your breathe in.","Step:7 Repeat for the recommended amount of repetitions."}','https://static.exercisedb.dev/media/vKilzz3.gif','https://static.exercisedb.dev/media/vKilzz3.gif',NULL),
('VLYXo8S','weighted round arm',NULL,'shoulders','delts','{"triceps","upper back"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Raise your arms out to the sides, keeping a slight bend in your elbows.","Step:4 Continue lifting your arms until they are parallel to the ground.","Step:5 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VLYXo8S.gif','https://static.exercisedb.dev/media/VLYXo8S.gif',NULL),
('vM5YS2g','reverse hyper extension (on stability ball)',NULL,'legs','glutes','{"hamstrings","lower back"}','other',NULL,'{"Step:1 Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.","Step:2 Place your hands on the ground in front of you for stability.","Step:3 Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vM5YS2g.gif','https://static.exercisedb.dev/media/vM5YS2g.gif',NULL),
('vmwLyCg','dumbbell w-press',NULL,'shoulders','delts','{"triceps","chest"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in each hand, palms facing forward.","Step:2 Raise the dumbbells to shoulder height, elbows bent and palms facing forward.","Step:3 Press the dumbbells upward until your arms are fully extended overhead.","Step:4 Lower the dumbbells back to shoulder height.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vmwLyCg.gif','https://static.exercisedb.dev/media/vmwLyCg.gif',NULL),
('vN5HB0s','blunt cable standing crunch',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Attach a cable handle to a high pulley and stand facing away from the machine.","Step:2 Hold the handle with both hands and place it behind your head, keeping your elbows bent.","Step:3 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:4 Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.","Step:5 Pause for a moment at the bottom of the movement, then slowly return to the starting position. Emphasize blunt control.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vN5HB0s.gif','https://static.exercisedb.dev/media/vN5HB0s.gif',NULL),
('VnfUNW7','close grip chin-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Step:2 Hang from the bar with your arms fully extended and your feet off the ground.","Step:3 Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Step:4 Continue pulling until your chin is above the bar.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VnfUNW7.gif','https://static.exercisedb.dev/media/VnfUNW7.gif',NULL),
('vNPJbDA','cable rope incline tricep extension - reverse variation',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.","Step:2 Stand facing away from the pulley with your feet shoulder-width apart.","Step:3 Grasp the rope with an overhand grip and extend your arms straight overhead.","Step:4 (reverse variation) Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Step:5 Lower the rope behind your head by bending your elbows until your forearms touch your biceps.","Step:6 Pause for a moment, then extend your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vNPJbDA.gif','https://static.exercisedb.dev/media/vNPJbDA.gif',NULL),
('VO2qeJg','side plank hip adduction',NULL,'legs','adductors','{"obliques","glutes"}','body weight',NULL,'{"Step:1 Start by lying on your side with your legs extended and stacked on top of each other.","Step:2 Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Step:3 Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Step:4 While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.","Step:5 Slowly lower your leg back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/VO2qeJg.gif','https://static.exercisedb.dev/media/VO2qeJg.gif',NULL),
('vobtVkm','calf push stretch with hands against wall elite',NULL,'legs','calves','{"hamstrings"}','body weight',NULL,'{"Step:1 Stand facing a wall with your feet hip-width apart.","Step:2 Place your hands against the wall at shoulder height.","Step:3 Step back with one foot, keeping your heel on the ground and your leg straight.","Step:4 Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Step:5 Hold the stretch for 20-30 seconds.","Step:6 Switch legs and repeat the stretch. Focus on elite movement."}','https://static.exercisedb.dev/media/vobtVkm.gif','https://static.exercisedb.dev/media/vobtVkm.gif',NULL),
('vocve3e','gentle style dumbbell one leg fly on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Step:2 Place one foot on the ground and extend the other leg straight out in front of you.","Step:3 Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.","Step:4 Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.","Step:5 (gentle variation) Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs and repeat."}','https://static.exercisedb.dev/media/vocve3e.gif','https://static.exercisedb.dev/media/vocve3e.gif',NULL),
('vpleANJ','inclined style pelvic tilt into bridge',NULL,'legs','glutes','{"hamstrings","core"}','body weight',NULL,'{"Step:1 Lie on your back with your knees bent and feet flat on the ground.","Step:2 Place your arms by your sides with your palms facing down.","Step:3 Engage your glutes and core muscles.","Step:4 Tilt your pelvis upward, lifting your hips off the ground. Emphasize inclined control.","Step:5 Hold the bridge position for a few seconds.","Step:6 Slowly lower your hips back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vpleANJ.gif','https://static.exercisedb.dev/media/vpleANJ.gif',NULL),
('vpp9Ku2','cable seated one arm alternate row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on a bench facing a cable machine with your feet flat on the ground and knees slightly bent.","Step:2 Grasp the handle with one hand and keep your arm fully extended in front of you.","Step:3 Pull the handle towards your body, retracting your shoulder blade and keeping your elbow close to your side.","Step:4 Pause for a moment at the top of the movement, squeezing your back muscles.","Step:5 Slowly release the handle back to the starting position.","Step:6 Repeat with the other arm.","Step:7 Alternate between arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/vpp9Ku2.gif','https://static.exercisedb.dev/media/vpp9Ku2.gif',NULL),
('VPPtusI','inverted row bent knees',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Set up a bar at waist height and lie underneath it.","Step:2 Grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Position your body so that your heels are on the ground and your body is straight.","Step:4 Pull your chest up towards the bar by squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VPPtusI.gif','https://static.exercisedb.dev/media/VPPtusI.gif',NULL),
('vpQaQkH','ski ergometer',NULL,'arms','triceps','{"shoulders","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and footrests to a comfortable position.","Step:2 Grasp the handles with an overhand grip, palms facing down.","Step:3 Sit up straight with your feet flat on the footrests.","Step:4 Extend your arms straight out in front of you, keeping your elbows slightly bent.","Step:5 Engage your triceps and push the handles down towards your thighs.","Step:6 Pause for a moment at the bottom, then slowly return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vpQaQkH.gif','https://static.exercisedb.dev/media/vpQaQkH.gif',NULL),
('vptOQ4N','deep push up',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Step:2 Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Step:3 Push through your palms to extend your arms and return to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vptOQ4N.gif','https://static.exercisedb.dev/media/vptOQ4N.gif',NULL),
('VQ3sNCn','dumbbell seated one arm kickback',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.","Step:2 Bend your torso forward at the waist, keeping your back straight and parallel to the ground.","Step:3 Extend your arm straight back, keeping your elbow close to your body.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/VQ3sNCn.gif','https://static.exercisedb.dev/media/VQ3sNCn.gif',NULL),
('vqsbmL0','lever shoulder press v. 2',NULL,'shoulders','delts','{"triceps","chest"}','machine',NULL,'{"Step:1 Adjust the seat height and backrest of the leverage machine to a comfortable position.","Step:2 Sit on the machine with your back against the backrest and your feet flat on the floor.","Step:3 Grasp the handles of the machine with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Push the handles upward and forward until your arms are fully extended, but not locked.","Step:5 Pause for a moment at the top, then slowly lower the handles back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vqsbmL0.gif','https://static.exercisedb.dev/media/vqsbmL0.gif',NULL),
('vR1vold','barbell full zercher squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and toes slightly turned out.","Step:2 Hold the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.","Step:3 Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Step:4 Keep your knees in line with your toes and your weight in your heels.","Step:5 Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:6 Drive through your heels to stand back up, squeezing your glutes at the top of the movement.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vR1vold.gif','https://static.exercisedb.dev/media/vR1vold.gif',NULL),
('VRBGPHB','single smith shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.","Step:2 (single variation) Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.","Step:4 Press the bar upward until your arms are fully extended overhead.","Step:5 Pause for a moment at the top, then slowly lower the bar back down to shoulder level.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VRBGPHB.gif','https://static.exercisedb.dev/media/VRBGPHB.gif',NULL),
('vrhHa6D','assisted parallel close grip pull-up',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the machine to your desired weight and height.","Step:2 Place your hands on the parallel bars with a close grip, palms facing each other.","Step:3 Hang from the bars with your arms fully extended and your feet off the ground.","Step:4 Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your body.","Step:5 Continue pulling until your chin is above the bars.","Step:6 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vrhHa6D.gif','https://static.exercisedb.dev/media/vrhHa6D.gif',NULL),
('vsMcDi9','barbell standing concentration curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.","Step:2 Rest your opposite hand on your thigh for support.","Step:3 Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the weight back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/vsMcDi9.gif','https://static.exercisedb.dev/media/vsMcDi9.gif',NULL),
('VsopqcV','macro style close-grip push-up',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands placed close together, directly under your shoulders.","Step:2 Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Step:3 Push through your palms to extend your arms and return to the starting position. Maintain macro form throughout.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VsopqcV.gif','https://static.exercisedb.dev/media/VsopqcV.gif',NULL),
('vsVoPHt','lever decline chest press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and backrest of the leverage machine to a comfortable position.","Step:2 Sit on the machine with your back against the backrest and your feet flat on the floor.","Step:3 Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Step:4 Push the handles forward and away from your body until your arms are fully extended.","Step:5 Slowly lower the handles back towards your chest, keeping your elbows slightly bent.","Step:6 Pause for a moment at the bottom, then push the handles back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vsVoPHt.gif','https://static.exercisedb.dev/media/vsVoPHt.gif',NULL),
('VtTbiP3','band pull through',NULL,'legs','glutes','{"hamstrings","lower back"}','resistance band',NULL,'{"Step:1 Attach a resistance band to a sturdy anchor point at ground level.","Step:2 Stand facing away from the anchor point with your feet shoulder-width apart.","Step:3 Step forward to create tension in the band, keeping your knees slightly bent.","Step:4 Hinge at the hips and push your glutes back, maintaining a slight bend in your knees.","Step:5 Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Step:6 Drive your hips forward and squeeze your glutes to return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VtTbiP3.gif','https://static.exercisedb.dev/media/VtTbiP3.gif',NULL),
('vtusOWT','barbell one arm floor press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Step:2 Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.","Step:3 Slowly lower the barbell towards your chest, keeping your elbow close to your body.","Step:4 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/vtusOWT.gif','https://static.exercisedb.dev/media/vtusOWT.gif',NULL),
('VuoerH0','triceps dip (bench leg)',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Step:2 Walk your feet forward, sliding your butt off the bench, and straighten your arms.","Step:3 Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Step:4 Push through your palms to straighten your arms and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VuoerH0.gif','https://static.exercisedb.dev/media/VuoerH0.gif',NULL),
('vUTfFHw','band wrist curl',NULL,'arms','forearms','{"biceps","triceps"}','resistance band',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground.","Step:2 Hold the band with both hands, palms facing up, and rest your forearms on your thighs.","Step:3 Slowly curl your wrists upward, squeezing your forearms.","Step:4 Pause for a moment at the top, then slowly lower your wrists back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vUTfFHw.gif','https://static.exercisedb.dev/media/vUTfFHw.gif',NULL),
('vvNjDJS','cable two arm tricep kickback',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Step:3 Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.","Step:4 Pause for a moment, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vvNjDJS.gif','https://static.exercisedb.dev/media/vvNjDJS.gif',NULL),
('Vvwjz6N','glute-ham raise',NULL,'legs','hamstrings','{"glutes","lower back"}','body weight',NULL,'{"Step:1 Adjust the glute-ham raise machine to fit your body.","Step:2 Position yourself face down on the machine with your ankles secured.","Step:3 Place your hands on your chest or cross them over your chest.","Step:4 Engage your hamstrings and glutes to lift your upper body up towards the ceiling.","Step:5 Continue lifting until your body is in a straight line from your head to your heels.","Step:6 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Vvwjz6N.gif','https://static.exercisedb.dev/media/Vvwjz6N.gif',NULL),
('VW88JNd','dumbbell seated one leg calf raise - palm up',NULL,'legs','calves','{"hamstrings","glutes"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your back straight and your feet flat on the ground.","Step:2 Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.","Step:3 Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.","Step:4 Raise your heel as high as possible by pushing through the ball of your foot.","Step:5 Pause for a moment at the top, then slowly lower your heel back down.","Step:6 Repeat for the desired number of repetitions, then switch legs and repeat."}','https://static.exercisedb.dev/media/VW88JNd.gif','https://static.exercisedb.dev/media/VW88JNd.gif',NULL),
('VX5YKR5','assisted lying leg raise with throw down',NULL,'core','abs','{"hip flexors","quadriceps"}','other',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms by your sides.","Step:2 Place your hands under your glutes for support.","Step:3 Engage your core and lift your legs off the ground, keeping them straight.","Step:4 Raise your legs until they are perpendicular to the ground.","Step:5 Lower your legs back down to the starting position.","Step:6 Simultaneously, throw your legs down towards the ground, keeping them straight.","Step:7 Raise your legs back up to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/VX5YKR5.gif','https://static.exercisedb.dev/media/VX5YKR5.gif',NULL),
('vYk8lqw','dumbbell incline rear lateral raise',NULL,'shoulders','delts','{"traps","rhomboids"}','dumbbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.","Step:3 Extend your arms straight down with your palms facing each other.","Step:4 Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Step:5 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vYk8lqw.gif','https://static.exercisedb.dev/media/vYk8lqw.gif',NULL),
('VYmYxK5','dumbbell one arm hammer press on exercise ball',NULL,'arms','triceps','{"shoulders","chest"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.","Step:3 Place your other hand on your hip for stability.","Step:4 Press the dumbbell upwards, extending your arm fully.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/VYmYxK5.gif','https://static.exercisedb.dev/media/VYmYxK5.gif',NULL),
('vzAxBtt','kettlebell one arm clean and jerk',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Step:2 Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.","Step:3 Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.","Step:4 As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.","Step:5 Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/vzAxBtt.gif','https://static.exercisedb.dev/media/vzAxBtt.gif',NULL),
('w1NOByi','band squat row',NULL,'legs','glutes','{"hamstrings","quadriceps","back"}','resistance band',NULL,'{"Step:1 Attach the band to a sturdy anchor point at waist height.","Step:2 Stand facing the anchor point with your feet shoulder-width apart.","Step:3 Hold the band handles with your palms facing each other and your arms extended in front of you.","Step:4 Bend your knees and lower into a squat position, keeping your back straight and chest lifted.","Step:5 From the squat position, pull the band handles towards your body, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly release the tension and return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/w1NOByi.gif','https://static.exercisedb.dev/media/w1NOByi.gif',NULL),
('W1p7BND','chest stretch with exercise ball partial',NULL,'chest','pectorals','{"shoulders","triceps"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your back straight.","Step:2 Hold the exercise ball with both hands and extend your arms straight out in front of you. Focus on partial movement.","Step:3 Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.","Step:4 Hold the stretch for a few seconds, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/W1p7BND.gif','https://static.exercisedb.dev/media/W1p7BND.gif',NULL),
('w2oRpuH','lever alternating narrow grip seated row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and footplate position to ensure proper alignment.","Step:2 Sit on the machine with your back straight and feet flat on the footplate.","Step:3 Grasp the handles with a narrow grip, palms facing each other.","Step:4 Keep your chest up and shoulders back throughout the exercise.","Step:5 Pull one handle towards your torso while keeping the other handle stationary.","Step:6 Squeeze your shoulder blades together at the end of the movement.","Step:7 Slowly return the handle to the starting position and repeat with the other side.","Step:8 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/w2oRpuH.gif','https://static.exercisedb.dev/media/w2oRpuH.gif',NULL),
('W31mMjd','barbell side split squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Step:2 Hold a barbell across your upper back, resting it on your traps.","Step:3 Engage your core and keep your chest up as you lower your body down into a squat position, bending at the knees and hips.","Step:4 As you lower, push your knees out to the sides and keep your weight on your heels.","Step:5 Lower until your thighs are parallel to the ground, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/W31mMjd.gif','https://static.exercisedb.dev/media/W31mMjd.gif',NULL),
('w44vFvP','smith one arm row linear',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the height of the smith machine bar to waist level.","Step:2 Stand facing the smith machine with your feet shoulder-width apart. Emphasize linear control.","Step:3 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:4 Grasp the bar with one hand using an overhand grip, with your palm facing down.","Step:5 Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/w44vFvP.gif','https://static.exercisedb.dev/media/w44vFvP.gif',NULL),
('w4dLzSx','cable one arm decline chest fly',NULL,'chest','pectorals','{"shoulders","triceps"}','cable',NULL,'{"Step:1 Attach a D-handle to a low pulley cable machine and set the bench to a decline angle.","Step:2 Lie down on the bench with your head towards the machine and grab the handle with your right hand.","Step:3 Extend your arm straight up above your chest, keeping a slight bend in your elbow.","Step:4 With a controlled motion, lower your arm out to the side until your hand is in line with your shoulder.","Step:5 Pause for a moment, then reverse the motion and bring your arm back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to your left arm and repeat the exercise."}','https://static.exercisedb.dev/media/w4dLzSx.gif','https://static.exercisedb.dev/media/w4dLzSx.gif',NULL),
('W6PxUkg','dumbbell kickback',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.","Step:4 Extend your arms straight back, squeezing your triceps at the top of the movement.","Step:5 Pause for a moment, then slowly lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/W6PxUkg.gif','https://static.exercisedb.dev/media/W6PxUkg.gif',NULL),
('w7obpWd','active style cable pushdown',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a straight bar to a high pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Step:3 Grasp the bar with an overhand grip, hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary.","Step:5 Exhale and push the bar down until your elbows are fully extended.","Step:6 Pause for a moment, then inhale and slowly return the bar to the starting position. Maintain active form throughout.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/w7obpWd.gif','https://static.exercisedb.dev/media/w7obpWd.gif',NULL),
('W7yh3Yo','wall style dumbbell one arm french press on exercise ball',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle. Focus on wall movement.","Step:3 Extend your arm straight up towards the ceiling, keeping your elbow stationary.","Step:4 Slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/W7yh3Yo.gif','https://static.exercisedb.dev/media/W7yh3Yo.gif',NULL),
('W8KAlkI','push-up medicine ball',NULL,'chest','pectorals','{"triceps","shoulders","core"}','medicine ball',NULL,'{"Step:1 Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Step:2 Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","Step:3 Push through your palms to extend your arms and return to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/W8KAlkI.gif','https://static.exercisedb.dev/media/W8KAlkI.gif',NULL),
('W9pFVv1','barbell bench squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Set up a barbell on a squat rack at chest height.","Step:2 Stand facing away from the rack, with your feet shoulder-width apart.","Step:3 Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Step:4 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:5 Lift the barbell off the rack and step back, ensuring your feet are still shoulder-width apart.","Step:6 Lower your body down into a squat, keeping your knees in line with your toes.","Step:7 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/W9pFVv1.gif','https://static.exercisedb.dev/media/W9pFVv1.gif',NULL),
('WbNq5Xu','lever standing chest press',NULL,'chest','pectorals','{"shoulders","triceps"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your feet flat on the ground.","Step:2 Grasp the handles with an overhand grip and position your hands at chest level.","Step:3 Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.","Step:4 Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/WbNq5Xu.gif','https://static.exercisedb.dev/media/WbNq5Xu.gif',NULL),
('wbUYILZ','elbow lift - reverse push-up',NULL,'back','upper back','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Start by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.","Step:2 Engage your core and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.","Step:3 Pause at the top for a moment, squeezing your upper back muscles.","Step:4 Slowly lower your body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wbUYILZ.gif','https://static.exercisedb.dev/media/wbUYILZ.gif',NULL),
('WCAvOfC','side-to-side toe touch (male)',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your arms extended to the sides.","Step:2 Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.","Step:3 Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.","Step:4 Repeat the side-to-side bending motion for the desired number of repetitions."}','https://static.exercisedb.dev/media/WCAvOfC.gif','https://static.exercisedb.dev/media/WCAvOfC.gif',NULL),
('WcHl7ru','smith close-grip bench press',NULL,'arms','triceps','{"chest","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the bench with your feet flat on the ground.","Step:2 Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Step:3 Lower the barbell towards your chest, keeping your elbows close to your body.","Step:4 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/WcHl7ru.gif','https://static.exercisedb.dev/media/WcHl7ru.gif',NULL),
('wd4ds3s','bodyweight standing row',NULL,'back','upper back','{"biceps","shoulders"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Grasp a bar or handles with an overhand grip, palms facing down.","Step:3 Keep your back straight and core engaged.","Step:4 Pull the bar or handles towards your body, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top of the movement.","Step:6 Slowly release and extend your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wd4ds3s.gif','https://static.exercisedb.dev/media/wd4ds3s.gif',NULL),
('wDN97Ca','machine inner chest press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back flat against the pad.","Step:2 Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.","Step:3 Push the handles forward until your arms are fully extended, exhaling during the movement.","Step:4 Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wDN97Ca.gif','https://static.exercisedb.dev/media/wDN97Ca.gif',NULL),
('wdRZISl','barbell standing close grip military press',NULL,'shoulders','delts','{"triceps","upper back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, hands slightly closer than shoulder-width apart.","Step:2 Lift the barbell to shoulder height, keeping your elbows close to your body.","Step:3 Press the barbell overhead, extending your arms fully.","Step:4 Lower the barbell back to shoulder height.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wdRZISl.gif','https://static.exercisedb.dev/media/wdRZISl.gif',NULL),
('wDUqY2u','cable overhead curl',NULL,'arms','biceps','{"forearms","shoulders"}','cable',NULL,'{"Step:1 Attach a straight bar to a high pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an underhand grip, hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary.","Step:5 Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.","Step:6 Pause for a moment at the bottom of the movement, squeezing your biceps.","Step:7 Inhale and slowly return the bar to the starting position, fully extending your arms.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wDUqY2u.gif','https://static.exercisedb.dev/media/wDUqY2u.gif',NULL),
('weoDEpH','captains chair straight leg raise',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Sit on the captain's chair with your back against the backrest and your forearms resting on the arm pads.","Step:2 Keep your upper body stable and your back straight.","Step:3 Engage your abs and lift your legs up in front of you, keeping them straight.","Step:4 Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Step:5 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/weoDEpH.gif','https://static.exercisedb.dev/media/weoDEpH.gif',NULL),
('wEulIzp','cable one arm lateral raise',NULL,'shoulders','delts','{"traps","triceps"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart, facing the cable machine.","Step:2 Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Step:3 Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/wEulIzp.gif','https://static.exercisedb.dev/media/wEulIzp.gif',NULL),
('wf24o8S','kettlebell two arm row',NULL,'back','upper back','{"biceps","forearms"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.","Step:2 Bend forward at the hips, keeping your back straight and your core engaged.","Step:3 Pull the kettlebells up towards your chest, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top, then slowly lower the kettlebells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wf24o8S.gif','https://static.exercisedb.dev/media/wf24o8S.gif',NULL),
('wfotm7S','bodyweight drop jump squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Jump up explosively, extending your hips, knees, and ankles.","Step:4 While in mid-air, quickly bring your feet together.","Step:5 Land softly on the balls of your feet and immediately drop back into a squat position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wfotm7S.gif','https://static.exercisedb.dev/media/wfotm7S.gif',NULL),
('WFucoe6','hanging straight twisting leg hip raise with compound',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your legs straight.","Step:2 Engage your core and lift your legs up towards your chest, keeping them straight. Perform with compound intensity.","Step:3 Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Step:4 Pause for a moment, then return to the starting position.","Step:5 Repeat the movement, but this time twist your hips to the opposite side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/WFucoe6.gif','https://static.exercisedb.dev/media/WFucoe6.gif',NULL),
('Wgaz7pm','lever seated crunch',NULL,'core','abs','{"obliques"}','machine',NULL,'{"Step:1 Sit on the leverage machine with your back against the pad and your feet flat on the floor.","Step:2 Grasp the handles or place your hands on the side pads for support.","Step:3 Engage your abs and slowly lean back, allowing the pad to move with you.","Step:4 Once your upper body is at a 45-degree angle, contract your abs and crunch forward, bringing your chest towards your knees.","Step:5 Pause for a moment at the top, then slowly release and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Wgaz7pm.gif','https://static.exercisedb.dev/media/Wgaz7pm.gif',NULL),
('Wgbn9qo','triceps dip (between benches)',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.","Step:2 Slide your butt off the bench, supporting your weight with your hands.","Step:3 Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Wgbn9qo.gif','https://static.exercisedb.dev/media/Wgbn9qo.gif',NULL),
('WgJnBH5','dumbbell seated biceps curl (on stability ball)',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Step:4 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/WgJnBH5.gif','https://static.exercisedb.dev/media/WgJnBH5.gif',NULL),
('WhuFnR7','lying leg raise flat bench',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on a flat bench with your back pressed against it.","Step:2 Place your hands under your glutes for support.","Step:3 Keep your legs straight and together, and lift them up towards the ceiling.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/WhuFnR7.gif','https://static.exercisedb.dev/media/WhuFnR7.gif',NULL),
('wi2H9QX','smith wide grip decline bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the decline bench to the desired angle.","Step:2 Lie down on the bench with your feet secured under the foot pads.","Step:3 Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.","Step:5 Pause for a moment when the barbell touches your chest.","Step:6 Push the barbell back up to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wi2H9QX.gif','https://static.exercisedb.dev/media/wi2H9QX.gif',NULL),
('wigSg76','clap push up',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart.","Step:2 Lower your body towards the ground by bending your elbows, keeping your core engaged.","Step:3 Push through your palms explosively to propel your body off the ground.","Step:4 While in mid-air, clap your hands together before landing back in the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wigSg76.gif','https://static.exercisedb.dev/media/wigSg76.gif',NULL),
('wkgnGfb','dumbbell incline hammer press on exercise ball',NULL,'arms','triceps','{"chest","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Step:2 Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.","Step:3 Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Step:4 Press the dumbbells up and slightly inward, keeping your palms facing each other.","Step:5 Extend your arms fully, squeezing your triceps at the top of the movement.","Step:6 Slowly lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wkgnGfb.gif','https://static.exercisedb.dev/media/wkgnGfb.gif',NULL),
('WKMQzCD','kettlebell lunge pass through',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands.","Step:2 Take a step forward with your right foot, lowering your body into a lunge position.","Step:3 As you lunge forward, pass the kettlebell under your right thigh and transfer it to your left hand.","Step:4 Push off with your right foot to return to the starting position, while simultaneously passing the kettlebell back to your right hand.","Step:5 Repeat the lunge on the opposite side, passing the kettlebell under your left thigh.","Step:6 Continue alternating lunges and passing the kettlebell between hands for the desired number of repetitions."}','https://static.exercisedb.dev/media/WKMQzCD.gif','https://static.exercisedb.dev/media/WKMQzCD.gif',NULL),
('WL4EmxJ','side bridge hip abduction',NULL,'legs','abductors','{"glutes","obliques"}','body weight',NULL,'{"Step:1 Lie on your side with your legs extended and stacked on top of each other.","Step:2 Prop yourself up on your forearm, keeping your elbow directly below your shoulder.","Step:3 Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.","Step:4 While keeping your core engaged, lift your top leg as high as possible without rotating your hips.","Step:5 Pause for a moment at the top, then lower your leg back down.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/WL4EmxJ.gif','https://static.exercisedb.dev/media/WL4EmxJ.gif',NULL),
('WLvTAv5','barbell prone incline curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Lie face down on the bench with your chest and stomach resting against it.","Step:3 Hold a barbell with an underhand grip, shoulder-width apart.","Step:4 Extend your arms fully, allowing the barbell to hang down towards the floor.","Step:5 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:6 Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.","Step:7 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:8 Inhale and slowly begin to lower the barbell back to the starting position.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/WLvTAv5.gif','https://static.exercisedb.dev/media/WLvTAv5.gif',NULL),
('WM6TvvW','cable low seated row controlled',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Step:2 Grasp the handles with an overhand grip, palms facing down.","Step:3 Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows. Maintain controlled form throughout.","Step:4 Pull the handles towards your body, squeezing your shoulder blades together.","Step:5 Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/WM6TvvW.gif','https://static.exercisedb.dev/media/WM6TvvW.gif',NULL),
('WME869U','exercise ball back extension with knees off ground',NULL,'back','spine','{"glutes","hamstrings"}','other',NULL,'{"Step:1 Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Step:2 Position your hands behind your head or crossed over your chest.","Step:3 Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/WME869U.gif','https://static.exercisedb.dev/media/WME869U.gif',NULL),
('wnEscH8','barbell press sit-up',NULL,'core','abs','{"shoulders","chest"}','barbell',NULL,'{"Step:1 Lie flat on your back on a mat with your knees bent and feet flat on the ground.","Step:2 Hold the barbell with an overhand grip, resting it on your chest.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wnEscH8.gif','https://static.exercisedb.dev/media/wnEscH8.gif',NULL),
('wOLmCXc','dumbbell tricep kickback with stork stance',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Step:4 Extend your right arm straight back, squeezing your triceps.","Step:5 Pause for a moment, then slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/wOLmCXc.gif','https://static.exercisedb.dev/media/wOLmCXc.gif',NULL),
('woLo1QN','incline push-up (on box) - active variation',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Place your hands on the edge of a box or elevated surface, slightly wider than shoulder-width apart.","Step:2 Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Step:3 Lower your chest towards the box by bending your elbows, keeping your body in a straight line.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Step:5 (active variation) Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/woLo1QN.gif','https://static.exercisedb.dev/media/woLo1QN.gif',NULL),
('wpbD28t','side push-up',NULL,'arms','triceps','{"shoulders","chest","core"}','body weight',NULL,'{"Step:1 Start by lying on your side with your legs extended and stacked on top of each other.","Step:2 Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.","Step:3 Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.","Step:4 Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.","Step:5 Lower your body back down to the starting position with control.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/wpbD28t.gif','https://static.exercisedb.dev/media/wpbD28t.gif',NULL),
('wPypxFY','cable side bend',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart and grasp the cable handle with one hand.","Step:2 Keep your back straight and your core engaged.","Step:3 Slowly bend sideways at the waist, lowering the cable handle towards your knee.","Step:4 Pause for a moment, then return to the starting position.","Step:5 Repeat on the other side.","Step:6 Alternate sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/wPypxFY.gif','https://static.exercisedb.dev/media/wPypxFY.gif',NULL),
('wQ2c4XD','barbell romanian deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your toes pointing forward.","Step:2 Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Bend at the hips, keeping your back straight and your knees slightly bent.","Step:4 Lower the barbell towards the ground, keeping it close to your body.","Step:5 Feel the stretch in your hamstrings as you lower the barbell.","Step:6 Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.","Step:7 Squeeze your glutes at the top of the movement.","Step:8 Lower the barbell back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wQ2c4XD.gif','https://static.exercisedb.dev/media/wQ2c4XD.gif',NULL),
('wqNPGCg','cable rear delt row (with rope)',NULL,'shoulders','delts','{"trapezius","rhomboids","biceps"}','cable',NULL,'{"Step:1 Attach a rope handle to a low pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the rope handle with an overhand grip, palms facing each other.","Step:4 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:5 Keep your elbows slightly bent and pull the rope towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement, then slowly release the tension and return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wqNPGCg.gif','https://static.exercisedb.dev/media/wqNPGCg.gif',NULL),
('WrYPP2g','cable one arm straight back high row (kneeling)',NULL,'back','upper back','{"biceps","shoulders"}','cable',NULL,'{"Step:1 Attach a handle to a cable machine at waist height.","Step:2 Kneel down facing the cable machine and grab the handle with one hand.","Step:3 Keep your back straight and your core engaged.","Step:4 Pull the handle towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top of the movement.","Step:6 Slowly release the handle back to the starting position.","Step:7 Repeat for the desired number of repetitions.","Step:8 Switch sides and repeat the exercise with the other arm."}','https://static.exercisedb.dev/media/WrYPP2g.gif','https://static.exercisedb.dev/media/WrYPP2g.gif',NULL),
('wSScovH','band bent-over hip extension',NULL,'legs','glutes','{"hamstrings","lower back"}','resistance band',NULL,'{"Step:1 Attach the band to a sturdy anchor point at ankle height.","Step:2 Stand facing away from the anchor point with your feet shoulder-width apart.","Step:3 Step back to create tension in the band, keeping your knees slightly bent.","Step:4 Hinge at the hips and lean forward, maintaining a neutral spine.","Step:5 Extend your right leg straight back, squeezing your glutes at the top.","Step:6 Lower your right leg back down and repeat with the left leg.","Step:7 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/wSScovH.gif','https://static.exercisedb.dev/media/wSScovH.gif',NULL),
('wt6rwjk','dumbbell palm rotational bent over row',NULL,'back','upper back','{"biceps","forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Step:2 Bend forward at the hips, keeping your back straight and your knees slightly bent.","Step:3 Let your arms hang straight down, palms facing your body.","Step:4 Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.","Step:5 As you pull the dumbbells up, rotate your palms so they face away from your body.","Step:6 Squeeze your shoulder blades together at the top of the movement.","Step:7 Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wt6rwjk.gif','https://static.exercisedb.dev/media/wt6rwjk.gif',NULL),
('wu5LXwz','olympic barbell triceps extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.","Step:2 Raise the barbell above your head, fully extending your arms.","Step:3 Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.","Step:4 Pause for a moment, then extend your arms back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wu5LXwz.gif','https://static.exercisedb.dev/media/wu5LXwz.gif',NULL),
('WU9BLIs','weighted russian twist (legs up)',NULL,'core','abs','{"obliques","hip flexors"}','other',NULL,'{"Step:1 Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.","Step:2 Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.","Step:3 Lean back slightly to engage your core muscles.","Step:4 Twist your torso to the right, bringing the weight towards the ground on your right side.","Step:5 Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/WU9BLIs.gif','https://static.exercisedb.dev/media/WU9BLIs.gif',NULL),
('WVD66ff','exercise ball back extension with rotation',NULL,'back','spine','{"glutes","hamstrings"}','other',NULL,'{"Step:1 Start by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.","Step:2 Place your hands behind your head or cross them over your chest.","Step:3 Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your heels.","Step:4 Pause for a moment at the top, then slowly rotate your torso to one side, keeping your hips and legs stable.","Step:5 Return to the center and repeat the rotation to the other side.","Step:6 Lower your upper body back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/WVD66ff.gif','https://static.exercisedb.dev/media/WVD66ff.gif',NULL),
('wVompEp','push up on bosu ball',NULL,'chest','pectorals','{"triceps","shoulders","core"}','other',NULL,'{"Step:1 Place the bosu ball on the ground with the flat side facing up.","Step:2 Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Step:3 Engage your core and lower your body down towards the bosu ball by bending your elbows.","Step:4 Push yourself back up to the starting position by extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wVompEp.gif','https://static.exercisedb.dev/media/wVompEp.gif',NULL),
('WW95auq','cable kneeling crunch',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Attach a rope handle to a high pulley and kneel down facing away from the machine.","Step:2 Hold the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.","Step:3 Keeping your hips stationary, flex your waist and crunch your torso down towards your thighs.","Step:4 Pause for a moment at the bottom, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/WW95auq.gif','https://static.exercisedb.dev/media/WW95auq.gif',NULL),
('WWD6FzI','sled 45 degrees one leg press',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the sled machine to a 45-degree angle.","Step:2 Sit on the sled machine with your back against the pad and your feet on the footplate.","Step:3 Place one foot on the footplate and extend your leg, pushing the sled away from you.","Step:4 Slowly bend your knee and lower the sled back to the starting position.","Step:5 Repeat with the other leg.","Step:6 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/WWD6FzI.gif','https://static.exercisedb.dev/media/WWD6FzI.gif',NULL),
('wWFspEi','smith single leg split squat',NULL,'legs','quads','{"glutes","hamstrings"}','machine',NULL,'{"Step:1 Stand in front of the smith machine with your feet shoulder-width apart.","Step:2 Place one foot behind you on a bench or step, with your toes pointing forward.","Step:3 Hold onto the smith machine bar for stability.","Step:4 Bend your front knee and lower your body down into a lunge position, keeping your back straight.","Step:5 Pause for a moment at the bottom, then push through your front heel to return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/wWFspEi.gif','https://static.exercisedb.dev/media/wWFspEi.gif',NULL),
('wXvUZC8','push and pull bodyweight',NULL,'chest','pectorals','{"triceps","deltoids"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Step:2 Lower your chest towards the ground by bending your elbows, keeping your body straight.","Step:3 Push through your palms to extend your arms and return to the starting position.","Step:4 From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight.","Step:5 Push through your palms to extend your arms and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/wXvUZC8.gif','https://static.exercisedb.dev/media/wXvUZC8.gif',NULL),
('wyaqzOS','dumbbell lying one arm pronated triceps extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Step:2 Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.","Step:3 Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Step:4 Pause for a moment at the bottom, then extend your arm back up to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/wyaqzOS.gif','https://static.exercisedb.dev/media/wyaqzOS.gif',NULL),
('x0lwvfq','dumbbell seated bent over alternate kickback',NULL,'arms','triceps','{"shoulders","back"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in each hand, palms facing inwards.","Step:2 Bend forward at the waist, keeping your back straight and parallel to the ground.","Step:3 Extend one arm straight back, keeping it close to your body, until your arm is fully extended.","Step:4 Pause for a moment, then slowly lower the dumbbell back to the starting position.","Step:5 Repeat with the other arm.","Step:6 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/x0lwvfq.gif','https://static.exercisedb.dev/media/x0lwvfq.gif',NULL),
('x2chWLO','neck side stretch',NULL,'other','levator scapulae','{"trapezius","sternocleidomastoid"}','body weight',NULL,'{"Step:1 Stand or sit up straight with your shoulders relaxed.","Step:2 Tilt your head to one side, bringing your ear towards your shoulder.","Step:3 Hold the stretch for 15-30 seconds.","Step:4 Repeat on the other side.","Step:5 Perform 2-4 sets on each side."}','https://static.exercisedb.dev/media/x2chWLO.gif','https://static.exercisedb.dev/media/x2chWLO.gif',NULL),
('x306lCW','dumbbell upright shoulder external rotation',NULL,'shoulders','delts','{"rotator cuff","trapezius"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Step:2 Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.","Step:3 Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/x306lCW.gif','https://static.exercisedb.dev/media/x306lCW.gif',NULL),
('X3cqyXz','lever bent over row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Bend forward at the hips, keeping your back straight and chest up.","Step:4 Pull the barbell towards your lower chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/X3cqyXz.gif','https://static.exercisedb.dev/media/X3cqyXz.gif',NULL),
('X3TCNEU','suspended abdominal fallout',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Step:2 Stand facing away from the anchor point and hold the handles with your arms extended in front of you.","Step:3 Lean forward at the waist, keeping your body straight and your core engaged.","Step:4 Lower your body as far as you can while maintaining control and tension in your abs.","Step:5 Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/X3TCNEU.gif','https://static.exercisedb.dev/media/X3TCNEU.gif',NULL),
('x69MAlq','cable straight arm pulldown',NULL,'back','lats','{"shoulders","biceps"}','cable',NULL,'{"Step:1 Attach a straight bar to the high pulley of a cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Step:4 Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.","Step:5 Pause for a moment at the bottom, then slowly return the bar to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/x69MAlq.gif','https://static.exercisedb.dev/media/x69MAlq.gif',NULL),
('X6C6i5Y','triceps dip',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.","Step:2 Slide your butt off the bench, supporting your weight with your hands.","Step:3 Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/X6C6i5Y.gif','https://static.exercisedb.dev/media/X6C6i5Y.gif',NULL),
('x6KpKpq','close-grip push-up',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands placed close together, directly under your shoulders.","Step:2 Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Step:3 Push through your palms to extend your arms and return to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/x6KpKpq.gif','https://static.exercisedb.dev/media/x6KpKpq.gif',NULL),
('X6ytgYZ','dumbbell side plank with rear fly',NULL,'back','upper back','{"shoulders","core"}','dumbbell',NULL,'{"Step:1 Start by lying on your side with your legs extended and stacked on top of each other.","Step:2 Place your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.","Step:3 Hold a dumbbell in your top hand, with your arm extended straight down towards the ground.","Step:4 Engage your core and lift your hips off the ground, creating a straight line from your head to your heels.","Step:5 While maintaining the side plank position, lift the dumbbell up towards the ceiling, squeezing your shoulder blades together.","Step:6 Lower the dumbbell back down to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/X6ytgYZ.gif','https://static.exercisedb.dev/media/X6ytgYZ.gif',NULL),
('X7jbxra','circles knee stretch',NULL,'legs','calves','{"hamstrings","quadriceps"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your hands on your hips.","Step:2 Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.","Step:3 Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.","Step:4 Perform the movement for the desired number of repetitions."}','https://static.exercisedb.dev/media/X7jbxra.gif','https://static.exercisedb.dev/media/X7jbxra.gif',NULL),
('x825CZm','cable seated rear lateral raise',NULL,'shoulders','delts','{"traps","rhomboids"}','cable',NULL,'{"Step:1 Sit on a bench facing the cable machine with your feet flat on the ground.","Step:2 Grasp the cable handles with an overhand grip and extend your arms straight in front of you.","Step:3 Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.","Step:4 Pause for a moment at the top, then slowly lower your arms back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/x825CZm.gif','https://static.exercisedb.dev/media/x825CZm.gif',NULL),
('XaaRnRn','incline reverse grip push-up',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.","Step:2 Extend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.","Step:3 Lower your chest towards the bench by bending your elbows, keeping them close to your sides.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XaaRnRn.gif','https://static.exercisedb.dev/media/XaaRnRn.gif',NULL),
('XalXcvM','dumbbell forward lunge triceps extension',NULL,'arms','triceps','{"shoulders","core"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Step:2 Take a step forward with your right foot, lowering your body into a lunge position.","Step:3 Keep your back straight and your chest up.","Step:4 Extend your arms straight overhead, keeping your elbows close to your ears.","Step:5 Lower the dumbbells behind your head by bending your elbows.","Step:6 Pause for a moment, then straighten your arms to return to the starting position.","Step:7 Repeat the movement for the desired number of repetitions, then switch legs and repeat."}','https://static.exercisedb.dev/media/XalXcvM.gif','https://static.exercisedb.dev/media/XalXcvM.gif',NULL),
('xAySMB0','balance board',NULL,'legs','quads','{"calves","hamstrings","glutes"}','body weight',NULL,'{"Step:1 Place the balance board on a flat surface.","Step:2 Step onto the balance board with one foot, ensuring it is centered.","Step:3 Slowly shift your weight onto the foot on the balance board, keeping your core engaged.","Step:4 Maintain your balance and stability as you hold the position for a desired amount of time.","Step:5 Repeat the exercise with the other foot."}','https://static.exercisedb.dev/media/xAySMB0.gif','https://static.exercisedb.dev/media/xAySMB0.gif',NULL),
('xbkPfaw','bodyweight standing one arm row',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand.","Step:2 Bend forward at the hips, keeping your back straight and your core engaged.","Step:3 Let the dumbbell hang straight down in front of you, with your arm fully extended.","Step:4 Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Step:5 Squeeze your shoulder blades together at the top of the movement.","Step:6 Lower the dumbbell back down to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/xbkPfaw.gif','https://static.exercisedb.dev/media/xbkPfaw.gif',NULL),
('xBYcQHj','cable underhand pulldown',NULL,'back','lats','{"biceps","forearms"}','cable',NULL,'{"Step:1 Adjust the cable machine so that the pulldown bar is at a height above your head.","Step:2 Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.","Step:3 Keep your back straight and lean back slightly.","Step:4 Pull the bar down towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xBYcQHj.gif','https://static.exercisedb.dev/media/xBYcQHj.gif',NULL),
('xcLntTC','slow leg pull in flat bench',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Sit on a flat bench with your legs extended straight out in front of you.","Step:2 Place your hands on the bench beside your hips for support.","Step:3 Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions. Maintain slow form throughout."}','https://static.exercisedb.dev/media/xcLntTC.gif','https://static.exercisedb.dev/media/xcLntTC.gif',NULL),
('Xd65M9w','dumbbell around pullover - intensive variation',NULL,'chest','pectorals','{"triceps","latissimus dorsi"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your head at one end and your feet firmly on the ground.","Step:2 Hold a dumbbell with both hands and extend your arms straight above your chest. Perform with intensive intensity.","Step:3 Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.","Step:4 Pause for a moment at the bottom, then raise the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Xd65M9w.gif','https://static.exercisedb.dev/media/Xd65M9w.gif',NULL),
('xDh0lJr','standing behind neck press',NULL,'shoulders','delts','{"triceps","upper back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.","Step:2 Keep your back straight and core engaged.","Step:3 Press the barbell overhead by extending your arms, fully extending your elbows.","Step:4 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xDh0lJr.gif','https://static.exercisedb.dev/media/xDh0lJr.gif',NULL),
('XDOiFns','sled forward angled calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.","Step:2 Place your hands on the handles or the sides of the machine for support.","Step:3 Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.","Step:4 Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XDOiFns.gif','https://static.exercisedb.dev/media/XDOiFns.gif',NULL),
('xdYPUtE','sissy squat',NULL,'legs','quads','{"calves","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your toes pointing slightly outward.","Step:2 Hold onto a stable object for balance if needed.","Step:3 Slowly lower your body by bending your knees and leaning back, keeping your torso upright.","Step:4 Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.","Step:5 Pause for a moment, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xdYPUtE.gif','https://static.exercisedb.dev/media/xdYPUtE.gif',NULL),
('XE93sQZ','dumbbell step up single leg balance with bicep curl - chair variation',NULL,'arms','biceps','{"quadriceps","glutes","hamstrings"}','dumbbell',NULL,'{"Step:1 Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.","Step:2 Place your right foot on the step, ensuring your entire foot is in contact with the surface.","Step:3 Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.","Step:4 At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.","Step:5 Lower the dumbbells back down and simultaneously lower your left foot back to the ground.","Step:6 (chair variation) Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/XE93sQZ.gif','https://static.exercisedb.dev/media/XE93sQZ.gif',NULL),
('XeMvLgE','roller body saw',NULL,'core','abs','{"shoulders","triceps","core"}','other',NULL,'{"Step:1 Start in a plank position with your forearms on the roller and your body in a straight line.","Step:2 Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.","Step:3 Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XeMvLgE.gif','https://static.exercisedb.dev/media/XeMvLgE.gif',NULL),
('XFc3vpY','resistance band seated biceps curl',NULL,'arms','biceps','{"forearms"}','resistance band',NULL,'{"Step:1 Sit on a chair or bench with your back straight and feet flat on the ground.","Step:2 Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.","Step:3 Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the resistance band back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XFc3vpY.gif','https://static.exercisedb.dev/media/XFc3vpY.gif',NULL),
('xGgAGPm','chair leg extended stretch',NULL,'legs','quads','{"hamstrings","calves"}','body weight',NULL,'{"Step:1 Sit on the edge of a chair with your back straight and feet flat on the ground.","Step:2 Extend one leg straight out in front of you, keeping your heel on the ground.","Step:3 Lean forward slightly, feeling a stretch in your quadriceps.","Step:4 Hold this position for 20-30 seconds.","Step:5 Switch legs and repeat the stretch."}','https://static.exercisedb.dev/media/xGgAGPm.gif','https://static.exercisedb.dev/media/xGgAGPm.gif',NULL),
('xgsGFVM','crab twist toe touch',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Start by sitting on the ground with your knees bent and feet flat on the floor.","Step:2 Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.","Step:3 Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.","Step:4 Return to the starting position and repeat on the other side.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/xgsGFVM.gif','https://static.exercisedb.dev/media/xgsGFVM.gif',NULL),
('XgWyAiA','chest dip (on dip-pull-up cage)',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Adjust the dip bars to a height that allows you to comfortably grip them.","Step:2 Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.","Step:3 Jump up and straighten your arms, supporting your body weight on the bars.","Step:4 Bend your knees and cross your ankles behind you.","Step:5 Lower your body by bending your elbows, keeping your chest up and your shoulders down.","Step:6 Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.","Step:7 Push through your palms and extend your elbows to raise your body back up to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XgWyAiA.gif','https://static.exercisedb.dev/media/XgWyAiA.gif',NULL),
('XhfS1DZ','peroneals stretch',NULL,'legs','calves','{"ankles","feet"}','other',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you.","Step:2 Loop the rope around the ball of your foot and hold the ends of the rope with your hands.","Step:3 Gently pull the rope towards you, flexing your foot and stretching your calf muscles.","Step:4 Hold the stretch for 15-30 seconds.","Step:5 Release the tension on the rope and repeat the stretch on the other leg.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XhfS1DZ.gif','https://static.exercisedb.dev/media/XhfS1DZ.gif',NULL),
('xHKN2s8','barbell one arm snatch',NULL,'shoulders','delts','{"traps","forearms","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Step:2 Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Step:4 Explosively extend your hips, knees, and ankles, driving the barbell upwards.","Step:5 As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.","Step:6 Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.","Step:7 Lower the barbell back down to the starting position in a controlled manner.","Step:8 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/xHKN2s8.gif','https://static.exercisedb.dev/media/xHKN2s8.gif',NULL),
('xi0yckC','barbell incline shoulder raise',NULL,'chest','serratus anterior','{"deltoids","trapezius"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on the bench with your back against the pad and feet flat on the ground.","Step:3 Hold a barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Lift the barbell up to shoulder height, keeping your elbows slightly bent.","Step:5 Slowly raise the barbell overhead, extending your arms fully.","Step:6 Pause for a moment at the top, then slowly lower the barbell back to shoulder height.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xi0yckC.gif','https://static.exercisedb.dev/media/xi0yckC.gif',NULL),
('xiA6lRr','dumbbell seated bicep curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Step:2 Keep your back straight and your elbows close to your torso.","Step:3 Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xiA6lRr.gif','https://static.exercisedb.dev/media/xiA6lRr.gif',NULL),
('xifhB5W','rear deltoid stretch',NULL,'shoulders','delts','{"trapezius","rhomboids"}','body weight',NULL,'{"Step:1 Stand tall with your feet shoulder-width apart.","Step:2 Extend your right arm across your chest, placing your left hand on your right elbow.","Step:3 Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.","Step:4 Hold the stretch for 15-30 seconds, then release.","Step:5 Repeat on the other side."}','https://static.exercisedb.dev/media/xifhB5W.gif','https://static.exercisedb.dev/media/xifhB5W.gif',NULL),
('XIHEoCG','standing calves',NULL,'legs','calves','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes pointing forward.","Step:2 Raise your heels off the ground as high as possible, standing on your toes.","Step:3 Hold the position for a moment, then slowly lower your heels back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XIHEoCG.gif','https://static.exercisedb.dev/media/XIHEoCG.gif',NULL),
('xiHiJcA','lever seated reverse fly (parallel grip)',NULL,'shoulders','delts','{"trapezius","rhomboids"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Step:2 Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.","Step:3 Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Step:4 Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xiHiJcA.gif','https://static.exercisedb.dev/media/xiHiJcA.gif',NULL),
('xLYSdtg','cable middle fly',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Attach cables to both sides of a cable machine at chest height.","Step:2 Stand in the center of the machine with one foot slightly in front of the other.","Step:3 Grasp the handles with an overhand grip and extend your arms out to the sides.","Step:4 Keep a slight bend in your elbows and maintain a slight forward lean.","Step:5 Engage your chest muscles and bring your arms forward in a sweeping motion.","Step:6 Pause for a moment at the center, then slowly return your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xLYSdtg.gif','https://static.exercisedb.dev/media/xLYSdtg.gif',NULL),
('XlZ4lAC','barbell good morning',NULL,'legs','hamstrings','{"lower back"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and the barbell resting on your upper back.","Step:2 Keeping your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.","Step:3 Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Step:4 Pause for a moment, then return to the starting position by squeezing your glutes and pushing your hips forward.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XlZ4lAC.gif','https://static.exercisedb.dev/media/XlZ4lAC.gif',NULL),
('xMjBKwn','dumbbell lateral to front raise',NULL,'shoulders','delts','{"trapezius","biceps"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Step:2 Keep your back straight and engage your core.","Step:3 Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.","Step:6 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xMjBKwn.gif','https://static.exercisedb.dev/media/xMjBKwn.gif',NULL),
('xmM75XG','weighted overhead crunch (on stability ball)',NULL,'core','abs','{"obliques","lower back"}','other',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Hold a weight plate or dumbbell with both hands and extend your arms overhead.","Step:3 Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.","Step:4 Pause for a moment at the top, then slowly lower your torso back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xmM75XG.gif','https://static.exercisedb.dev/media/xmM75XG.gif',NULL),
('xmWQIlT','hold style dumbbell alternating seated bicep curl on exercise ball',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.","Step:4 (hold variation) Inhale and slowly lower the dumbbell back to the starting position.","Step:5 Repeat the curl with the other arm.","Step:6 Continue alternating curls for the desired number of repetitions."}','https://static.exercisedb.dev/media/xmWQIlT.gif','https://static.exercisedb.dev/media/xmWQIlT.gif',NULL),
('xnInPfE','barbell standing ab rollerout',NULL,'core','abs','{"shoulders","lower back"}','barbell',NULL,'{"Step:1 Stand upright with your feet shoulder-width apart and hold the barbell with both hands in front of your thighs.","Step:2 Engage your core and slowly roll the barbell down towards the ground, keeping your back straight and your arms extended.","Step:3 Continue rolling the barbell forward until your body is fully extended and your hands are directly above your head.","Step:4 Pause for a moment, then slowly roll the barbell back towards your thighs, maintaining control and keeping your core engaged.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xnInPfE.gif','https://static.exercisedb.dev/media/xnInPfE.gif',NULL),
('xNrS20v','barbell reverse curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Step:2 Keep your upper arms stationary and exhale as you curl the barbell upward, contracting your biceps.","Step:3 Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale as you slowly lower the barbell back to the starting position, keeping your upper arms stationary.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xNrS20v.gif','https://static.exercisedb.dev/media/xNrS20v.gif',NULL),
('xo6sENf','exercise ball on the wall calf raise',NULL,'legs','calves','{"hamstrings","quadriceps"}','dumbbell',NULL,'{"Step:1 Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Step:2 Position your feet shoulder-width apart, with your toes pointing forward.","Step:3 Hold a dumbbell in each hand, with your arms extended by your sides.","Step:4 Raise your heels off the ground, lifting your body weight onto the balls of your feet.","Step:5 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xo6sENf.gif','https://static.exercisedb.dev/media/xo6sENf.gif',NULL),
('XooAdhl','handstand',NULL,'arms','triceps','{"shoulders","core"}','body weight',NULL,'{"Step:1 Find an open space with enough room to perform a handstand.","Step:2 Place your hands on the ground shoulder-width apart, fingers pointing forward.","Step:3 Kick your legs up towards the wall, using your core and shoulders to maintain balance.","Step:4 Once in a handstand position, engage your triceps to support your body weight.","Step:5 Hold the handstand for as long as you can maintain balance.","Step:6 To come down, slowly lower your legs back to the ground.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XooAdhl.gif','https://static.exercisedb.dev/media/XooAdhl.gif',NULL),
('xOXZJRZ','clock push-up extreme',NULL,'chest','pectorals','{"triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Step:3 As you lower, rotate your body to the left, extending your left arm straight out to the side. Focus on extreme movement.","Step:4 Push back up to the starting position, while rotating your body to the center.","Step:5 Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.","Step:6 Continue alternating sides with each repetition."}','https://static.exercisedb.dev/media/xOXZJRZ.gif','https://static.exercisedb.dev/media/xOXZJRZ.gif',NULL),
('XPUDTt7','pike-to-cobra push-up',NULL,'legs','glutes','{"core","shoulders","triceps"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Step:2 Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body.","Step:3 Lower your upper body towards the ground by bending your elbows, keeping them close to your body.","Step:4 As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up.","Step:5 Reverse the movement by bending your elbows and lowering your chest back down towards the ground.","Step:6 Push through your hands to return to the inverted V position.","Step:7 Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XPUDTt7.gif','https://static.exercisedb.dev/media/XPUDTt7.gif',NULL),
('XqYQ9JA','dumbbell one arm prone hammer curl - macro variation',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.","Step:2 Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.","Step:3 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:4 Repeat for the desired number of repetitions, then switch arms. Focus on macro movement."}','https://static.exercisedb.dev/media/XqYQ9JA.gif','https://static.exercisedb.dev/media/XqYQ9JA.gif',NULL),
('XsCcxCC','lever seated good morning',NULL,'legs','glutes','{"hamstrings","lower back"}','machine',NULL,'{"Step:1 Adjust the seat height so that your hips are slightly higher than your knees.","Step:2 Sit on the machine with your back against the pad and your feet flat on the footrests.","Step:3 Grasp the handles or the sides of the seat for stability.","Step:4 Keeping your back straight, slowly lean forward from your hips until your upper body is parallel to the ground.","Step:5 Pause for a moment, then slowly return to the starting position by pushing through your glutes and hamstrings.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XsCcxCC.gif','https://static.exercisedb.dev/media/XsCcxCC.gif',NULL),
('XSCHmiI','cycle cross trainer',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the cycle cross trainer.","Step:2 Place your feet on the pedals and grip the handlebars.","Step:3 Start pedaling in a smooth and controlled motion.","Step:4 Maintain a steady pace and increase the resistance if desired.","Step:5 Continue pedaling for the desired duration of your cardio workout."}','https://static.exercisedb.dev/media/XSCHmiI.gif','https://static.exercisedb.dev/media/XSCHmiI.gif',NULL),
('xTjr103','standing hamstring and calf stretch with strap',NULL,'legs','hamstrings','{"calves"}','other',NULL,'{"Step:1 Stand upright with your feet shoulder-width apart.","Step:2 Hold the strap with both hands and place it around the ball of your foot.","Step:3 Keep your leg straight and slowly lean forward from your hips, keeping your back straight.","Step:4 Feel the stretch in your hamstring and calf muscles.","Step:5 Hold the stretch for 20-30 seconds.","Step:6 Release the stretch and repeat with the other leg.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xTjr103.gif','https://static.exercisedb.dev/media/xTjr103.gif',NULL),
('XU3ePuv','cable standing crunch (with rope attachment)',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Attach a rope to a cable machine at chest height.","Step:2 Stand facing away from the machine with your feet shoulder-width apart.","Step:3 Hold the rope with both hands and bring it behind your head, keeping your elbows bent.","Step:4 Engage your abs and slowly crunch your torso forward, bringing your elbows towards your knees.","Step:5 Pause for a moment at the top of the crunch, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XU3ePuv.gif','https://static.exercisedb.dev/media/XU3ePuv.gif',NULL),
('XUUD0Fs','dumbbell lying rear delt row',NULL,'back','upper back','{"shoulders","biceps"}','dumbbell',NULL,'{"Step:1 Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.","Step:2 Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Step:3 Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XUUD0Fs.gif','https://static.exercisedb.dev/media/XUUD0Fs.gif',NULL),
('xUwnBMT','smith seated shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','machine',NULL,'{"Step:1 Adjust the seat height so that the handles are at shoulder level.","Step:2 Sit on the machine with your back against the pad and your feet flat on the floor.","Step:3 Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.","Step:4 Lower the handles down to shoulder level, keeping your elbows slightly bent.","Step:5 Press the handles up overhead until your arms are fully extended.","Step:6 Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xUwnBMT.gif','https://static.exercisedb.dev/media/xUwnBMT.gif',NULL),
('XVDdcoj','russian twist',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Sit on the ground with your knees bent and feet flat on the floor.","Step:2 Lean back slightly while keeping your back straight and your core engaged.","Step:3 Hold your hands together in front of your chest or hold a weight if desired.","Step:4 Lift your feet off the ground, balancing on your sit bones.","Step:5 Twist your torso to the right, bringing your hands or weight towards the right side of your body.","Step:6 Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/XVDdcoj.gif','https://static.exercisedb.dev/media/XVDdcoj.gif',NULL),
('XVzF3iZ','dumbbell lying supine biceps curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Step:2 Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/XVzF3iZ.gif','https://static.exercisedb.dev/media/XVzF3iZ.gif',NULL),
('xXm4nYq','dumbbell decline fly',NULL,'chest','pectorals','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie on a decline bench with your feet secured and your head lower than your hips.","Step:2 Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Step:3 Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Step:4 Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/xXm4nYq.gif','https://static.exercisedb.dev/media/xXm4nYq.gif',NULL),
('Xy4jlWA','dumbbell arnold press',NULL,'shoulders','delts','{"triceps","upper chest"}','dumbbell',NULL,'{"Step:1 Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Step:2 Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Step:3 Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Xy4jlWA.gif','https://static.exercisedb.dev/media/Xy4jlWA.gif',NULL),
('Y1MsI1l','resistance band leg extension',NULL,'legs','quads','{"hamstrings"}','resistance band',NULL,'{"Step:1 Attach the resistance band to a sturdy anchor point and secure it around your ankle.","Step:2 Stand facing the anchor point with your feet shoulder-width apart.","Step:3 Keeping your core engaged and your upper body stable, extend your leg straight out in front of you.","Step:4 Pause for a moment at the top, then slowly return your leg to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/Y1MsI1l.gif','https://static.exercisedb.dev/media/Y1MsI1l.gif',NULL),
('Y4BRNQF','push-up (on stability ball)',NULL,'chest','pectorals','{"triceps","shoulders","core"}','other',NULL,'{"Step:1 Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart.","Step:2 Extend your legs straight out behind you, balancing on your toes.","Step:3 Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Y4BRNQF.gif','https://static.exercisedb.dev/media/Y4BRNQF.gif',NULL),
('Y4QlY8z','smith toe raise',NULL,'legs','calves','{"ankles","shins"}','machine',NULL,'{"Step:1 Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.","Step:2 Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.","Step:3 Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.","Step:4 Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:5 Engage your core and keep your back straight throughout the exercise.","Step:6 Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Step:7 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Y4QlY8z.gif','https://static.exercisedb.dev/media/Y4QlY8z.gif',NULL),
('y5p0H8a','run (equipment)',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Start by standing upright with your feet hip-width apart.","Step:2 Engage your core and keep your upper body relaxed.","Step:3 Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Step:4 Maintain a steady pace and continue jogging for the desired duration or distance.","Step:5 Remember to breathe deeply and maintain good posture throughout the exercise."}','https://static.exercisedb.dev/media/y5p0H8a.gif','https://static.exercisedb.dev/media/y5p0H8a.gif',NULL),
('y5U5B9Y','dumbbell zottman preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.","Step:2 Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.","Step:3 At the top of the curl, rotate your wrists so that your palms are facing down.","Step:4 Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/y5U5B9Y.gif','https://static.exercisedb.dev/media/y5U5B9Y.gif',NULL),
('Y5X65IB','ez barbell reverse grip curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.","Step:2 Keep your elbows close to your torso and your upper arms stationary throughout the exercise.","Step:3 Curl the barbell upwards by contracting your biceps, while exhaling.","Step:4 Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Slowly begin to bring the barbell back to the starting position as you inhale.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Y5X65IB.gif','https://static.exercisedb.dev/media/Y5X65IB.gif',NULL),
('Y7YcmIJ','barbell bench front squat',NULL,'legs','quads','{"hamstrings","glutes","calves"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, just below your collarbone.","Step:2 Hold the barbell with an overhand grip, keeping your elbows up and your upper arms parallel to the ground.","Step:3 Lower your body down into a squat position by bending at the knees and hips, keeping your back straight and your chest up.","Step:4 Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Y7YcmIJ.gif','https://static.exercisedb.dev/media/Y7YcmIJ.gif',NULL),
('y8bYM8w','band single leg split squat',NULL,'legs','quads','{"glutes","hamstrings"}','resistance band',NULL,'{"Step:1 Stand with your feet hip-width apart and place a resistance band around your ankles.","Step:2 Take a big step forward with your right foot and a smaller step back with your left foot.","Step:3 Bend your knees and lower your body until your right thigh is parallel to the ground, keeping your left knee slightly above the ground.","Step:4 Push through your right heel to return to the starting position.","Step:5 Repeat on the other side."}','https://static.exercisedb.dev/media/y8bYM8w.gif','https://static.exercisedb.dev/media/y8bYM8w.gif',NULL),
('Y8dOJlH','cable squat row (with rope attachment) heavy',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Attach a rope to a cable machine at waist height.","Step:2 Stand facing the cable machine with your feet shoulder-width apart.","Step:3 (heavy variation) Bend your knees and lower your body into a squat position, keeping your back straight and chest up.","Step:4 Grasp the rope with an overhand grip, with your hands shoulder-width apart.","Step:5 Engage your core and pull the rope towards your body, squeezing your shoulder blades together.","Step:6 Keep your elbows close to your body and continue pulling until your hands reach your chest.","Step:7 Pause for a moment at the top of the movement, then slowly release the rope and extend your arms back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Y8dOJlH.gif','https://static.exercisedb.dev/media/Y8dOJlH.gif',NULL),
('Y9hNPcN','seated side crunch (wall)',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Sit on the floor with your back against a wall and your legs extended in front of you.","Step:2 Bend your knees and place your feet flat on the floor, hip-width apart.","Step:3 Place your hands behind your head with your elbows pointing outwards.","Step:4 Engage your abs and lean to one side, bringing your elbow towards your hip.","Step:5 Pause for a moment, then return to the starting position.","Step:6 Repeat on the other side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/Y9hNPcN.gif','https://static.exercisedb.dev/media/Y9hNPcN.gif',NULL),
('YA2HKGz','barbell reverse wrist curl - prone variation',NULL,'arms','forearms','{"biceps","brachialis"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Step:2 Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Step:3 Slowly curl your wrists upward, bringing the barbell towards your body. Emphasize prone control.","Step:4 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/YA2HKGz.gif','https://static.exercisedb.dev/media/YA2HKGz.gif',NULL),
('yaAxcQr','rope climb',NULL,'back','upper back','{"forearms","biceps","shoulders"}','other',NULL,'{"Step:1 Stand facing the rope with your feet shoulder-width apart.","Step:2 Grab the rope with both hands, palms facing towards you.","Step:3 Bend your knees slightly and engage your core.","Step:4 Begin pulling yourself up the rope by alternating hand-over-hand movements.","Step:5 Use your legs to assist in the upward movement.","Step:6 Continue climbing until you reach the desired height or the top of the rope.","Step:7 To descend, reverse the hand-over-hand movement while controlling your descent.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yaAxcQr.gif','https://static.exercisedb.dev/media/yaAxcQr.gif',NULL),
('YAk5dIw','reverse grip pull-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Grab the pull-up bar with an underhand grip, hands shoulder-width apart.","Step:2 Hang from the bar with your arms fully extended and your body straight.","Step:3 Engage your back muscles and pull your body up towards the bar, leading with your chest.","Step:4 Continue pulling until your chin is above the bar.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/YAk5dIw.gif','https://static.exercisedb.dev/media/YAk5dIw.gif',NULL),
('yaMIo4D','cable incline bench row',NULL,'back','upper back','{"biceps","rear deltoids"}','cable',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle and attach a cable handle to the low pulley.","Step:2 Sit on the bench facing the cable machine with your feet flat on the floor and your knees slightly bent.","Step:3 Grasp the cable handle with an overhand grip and extend your arms fully in front of you.","Step:4 Lean forward from your hips while keeping your back straight and your core engaged.","Step:5 Pull the cable handle towards your chest by retracting your shoulder blades and bending your elbows.","Step:6 Squeeze your back muscles at the top of the movement, then slowly extend your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yaMIo4D.gif','https://static.exercisedb.dev/media/yaMIo4D.gif',NULL),
('yB9SvIF','smith machine decline close grip bench press',NULL,'arms','triceps','{"chest","shoulders"}','machine',NULL,'{"Step:1 Adjust the bench on the smith machine to a decline position.","Step:2 Lie down on the bench with your feet firmly planted on the ground.","Step:3 Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Step:5 Pause for a moment when the barbell is just above your chest.","Step:6 Push the barbell back up to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yB9SvIF.gif','https://static.exercisedb.dev/media/yB9SvIF.gif',NULL),
('yCvYdi7','kettlebell one arm military press to the side',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.","Step:2 Engage your core and keep your back straight.","Step:3 Press the kettlebell overhead, extending your arm fully.","Step:4 Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/yCvYdi7.gif','https://static.exercisedb.dev/media/yCvYdi7.gif',NULL),
('Ye5Qxb0','ez barbell spider curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.","Step:2 Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.","Step:3 Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ye5Qxb0.gif','https://static.exercisedb.dev/media/Ye5Qxb0.gif',NULL),
('ye84CTU','lever preacher curl v. 2',NULL,'arms','biceps','{"forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your upper arms resting on the pad and your chest against the support.","Step:2 Grasp the handles with an underhand grip, slightly wider than shoulder-width apart.","Step:3 Keep your upper arms stationary and exhale as you curl the handles towards your shoulders, contracting your biceps.","Step:4 Pause for a moment at the top of the movement, squeezing your biceps.","Step:5 Inhale as you slowly lower the handles back to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ye84CTU.gif','https://static.exercisedb.dev/media/ye84CTU.gif',NULL),
('Yg7MJAT','dumbbell one arm lateral raise with support',NULL,'shoulders','delts','{"trapezius","rotator cuff"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.","Step:2 Place your other hand on a stable surface, such as a bench or wall, for support.","Step:3 Keep your back straight and engage your core.","Step:4 Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.","Step:5 Continue lifting until your arm is parallel to the ground.","Step:6 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/Yg7MJAT.gif','https://static.exercisedb.dev/media/Yg7MJAT.gif',NULL),
('yg8Totb','barbell lying back of the head tricep extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Step:3 Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Step:4 Pause for a moment, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yg8Totb.gif','https://static.exercisedb.dev/media/yg8Totb.gif',NULL),
('YIUAtYf','weighted russian twist v. 2',NULL,'core','abs','{"obliques","lower back"}','other',NULL,'{"Step:1 Sit on the ground with your knees bent and feet flat on the floor.","Step:2 Hold the weight with both hands in front of your chest.","Step:3 Lean back slightly to engage your core muscles.","Step:4 Twist your torso to the right, bringing the weight towards the right side of your body.","Step:5 Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/YIUAtYf.gif','https://static.exercisedb.dev/media/YIUAtYf.gif',NULL),
('yJUHKTn','muscle up',NULL,'back','lats','{"biceps","triceps","shoulders","chest"}','body weight',NULL,'{"Step:1 Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.","Step:2 Engage your core and pull your body up towards the bar, leading with your chest.","Step:3 As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Step:4 Continue pulling yourself up until your chest is above the bar and your arms are fully flexed.","Step:5 Reverse the movement by slowly lowering yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yJUHKTn.gif','https://static.exercisedb.dev/media/yJUHKTn.gif',NULL),
('ykA5tU7','chest stretch with exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your back straight.","Step:2 Hold the exercise ball with both hands and extend your arms straight out in front of you.","Step:3 Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.","Step:4 Hold the stretch for a few seconds, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ykA5tU7.gif','https://static.exercisedb.dev/media/ykA5tU7.gif',NULL),
('ykHcWme','sled calf press on leg press',NULL,'legs','calves','{"hamstrings","quadriceps"}','machine',NULL,'{"Step:1 Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.","Step:2 Place your feet shoulder-width apart on the sled, with your toes pointing forward.","Step:3 Release the safety handles and push the sled away from you by extending your knees and ankles.","Step:4 Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ykHcWme.gif','https://static.exercisedb.dev/media/ykHcWme.gif',NULL),
('ykUOVze','lever standing calf raise',NULL,'legs','calves','{"soleus","ankle stabilizers"}','machine',NULL,'{"Step:1 Adjust the machine to your height and stand with your feet shoulder-width apart.","Step:2 Place your shoulders under the pads and hold onto the handles for stability.","Step:3 Raise your heels as high as possible by extending your ankles.","Step:4 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ykUOVze.gif','https://static.exercisedb.dev/media/ykUOVze.gif',NULL),
('yl2IYyy','cable standing calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','cable',NULL,'{"Step:1 Stand facing a cable machine with your feet shoulder-width apart.","Step:2 Hold onto the cable machine handles or attach a cable ankle strap to your ankles.","Step:3 Raise your heels off the ground by extending your ankles as high as possible.","Step:4 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yl2IYyy.gif','https://static.exercisedb.dev/media/yl2IYyy.gif',NULL),
('yn0LjwL','assisted lying glutes stretch',NULL,'legs','glutes','{"hamstrings"}','other',NULL,'{"Step:1 Lie on your back with your legs extended.","Step:2 Bend your right knee and place your right ankle on your left thigh, just above the knee.","Step:3 Grasp your left thigh with both hands and gently pull it towards your chest.","Step:4 Hold the stretch for 20-30 seconds.","Step:5 Release and repeat on the other side."}','https://static.exercisedb.dev/media/yn0LjwL.gif','https://static.exercisedb.dev/media/yn0LjwL.gif',NULL),
('yn2lLSI','sled 45в° leg press (back pov)',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the seat of the sled machine so that your knees are at a 45-degree angle.","Step:2 Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.","Step:3 Grip the handles on the sides of the seat for stability.","Step:4 Push the footplate away from your body by extending your legs, keeping your heels on the footplate.","Step:5 Pause for a moment at the fully extended position.","Step:6 Slowly bend your knees and lower the footplate back towards your body, controlling the movement.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yn2lLSI.gif','https://static.exercisedb.dev/media/yn2lLSI.gif',NULL),
('yn8yg1r','dumbbell goblet squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.","Step:2 Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.","Step:3 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:4 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yn8yg1r.gif','https://static.exercisedb.dev/media/yn8yg1r.gif',NULL),
('YPoVrBi','cable seated shoulder internal rotation',NULL,'shoulders','delts','{"rotator cuff","triceps"}','cable',NULL,'{"Step:1 Sit on a bench or chair facing the cable machine with your feet flat on the ground.","Step:2 Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.","Step:3 Keep your elbow slightly bent and your shoulder blades pulled back and down.","Step:4 Slowly rotate your arm inward, bringing the cable handle towards the center of your body.","Step:5 Pause for a moment at the end of the movement, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/YPoVrBi.gif','https://static.exercisedb.dev/media/YPoVrBi.gif',NULL),
('yq3GAJX','hands reversed clasped circular toe touch (male)',NULL,'legs','glutes','{"hamstrings","quadriceps","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your arms extended to the sides.","Step:2 Bend forward at the waist, keeping your back straight and your knees slightly bent.","Step:3 Reach down with your hands and clasp them together behind your legs.","Step:4 Slowly raise your hands up and over your head in a circular motion, keeping your legs straight.","Step:5 Continue the circular motion until your hands touch your toes.","Step:6 Reverse the motion and bring your hands back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yq3GAJX.gif','https://static.exercisedb.dev/media/yq3GAJX.gif',NULL),
('yQe5HpE','barbell standing twist',NULL,'core','abs','{"obliques","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell in front of your chest with both hands, palms facing down.","Step:2 Engage your core and keep your back straight throughout the exercise.","Step:3 Slowly twist your torso to the right, pivoting on your feet and hips, while keeping your lower body stable.","Step:4 Pause for a moment at the end of the twist, then slowly return to the starting position.","Step:5 Repeat the twist to the left side.","Step:6 Continue alternating twists for the desired number of repetitions."}','https://static.exercisedb.dev/media/yQe5HpE.gif','https://static.exercisedb.dev/media/yQe5HpE.gif',NULL),
('YqJw82s','barbell reverse close-grip bench press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the barbell with a reverse grip, hands shoulder-width apart.","Step:3 Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Step:4 Slowly lower the barbell down towards your chest, keeping your elbows close to your body.","Step:5 Pause for a moment when the barbell is just above your chest.","Step:6 Push the barbell back up to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/YqJw82s.gif','https://static.exercisedb.dev/media/YqJw82s.gif',NULL),
('YRaCa5Y','full maltese',NULL,'core','abs','{"shoulders","chest"}','body weight',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and your arms extended straight out to the sides.","Step:2 Slowly lean forward, keeping your arms straight, until your upper body is parallel to the ground.","Step:3 Engage your core and hold this position for a few seconds.","Step:4 Return to the starting position by pushing through your feet and standing back up.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/YRaCa5Y.gif','https://static.exercisedb.dev/media/YRaCa5Y.gif',NULL),
('yRLPCLu','barbell reverse grip skullcrusher',NULL,'arms','triceps','{"forearms"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.","Step:3 Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.","Step:4 Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Step:5 Pause for a moment at the bottom, then extend your arms back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yRLPCLu.gif','https://static.exercisedb.dev/media/yRLPCLu.gif',NULL),
('yRpV5TC','shoulder tap',NULL,'core','abs','{"shoulders","triceps"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.","Step:3 Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.","Step:4 Continue alternating shoulder taps while keeping your hips and torso stable.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yRpV5TC.gif','https://static.exercisedb.dev/media/yRpV5TC.gif',NULL),
('yRYyfdA','exercise ball seated hamstring stretch',NULL,'legs','hamstrings','{"glutes","lower back"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.","Step:3 Place your hands on your hips for support.","Step:4 Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.","Step:5 Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.","Step:6 Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yRYyfdA.gif','https://static.exercisedb.dev/media/yRYyfdA.gif',NULL),
('Ys97II0','dumbbell seated front raise',NULL,'shoulders','delts','{"trapezius","biceps"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Step:2 Keep your back straight and core engaged.","Step:3 Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ys97II0.gif','https://static.exercisedb.dev/media/Ys97II0.gif',NULL),
('yT9tk17','twisted leg raise (female)',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms by your sides.","Step:2 Bend your knees and lift your legs off the ground, bringing them towards your chest.","Step:3 As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat the movement, this time twisting your hips to the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/yT9tk17.gif','https://static.exercisedb.dev/media/yT9tk17.gif',NULL),
('YtaCTYl','dumbbell one arm seated neutral wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Step:2 Rest your forearm on your thigh, allowing your wrist to hang off the edge.","Step:3 Keeping your forearm stationary, curl your wrist upward as far as possible.","Step:4 Pause for a moment at the top, then slowly lower your wrist back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other hand."}','https://static.exercisedb.dev/media/YtaCTYl.gif','https://static.exercisedb.dev/media/YtaCTYl.gif',NULL),
('YtgD7Xq','shoulder grip pull-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Grab the pull-up bar with a shoulder-width grip, palms facing away from you.","Step:2 Hang freely with your arms fully extended.","Step:3 Engage your back muscles and pull your body up towards the bar until your chin is above the bar.","Step:4 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/YtgD7Xq.gif','https://static.exercisedb.dev/media/YtgD7Xq.gif',NULL),
('YTur5nR','cable one arm curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Stand facing the cable machine with your feet shoulder-width apart.","Step:2 Grasp the cable handle with an underhand grip, palm facing up.","Step:3 Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Step:4 Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/YTur5nR.gif','https://static.exercisedb.dev/media/YTur5nR.gif',NULL),
('yU7w7CA','exercise ball lower back stretch (pyramid)',NULL,'back','lats','{"glutes","hamstrings"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Slowly walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.","Step:3 Place your hands behind your head or cross them over your chest.","Step:4 Engage your core and slowly lower your upper body towards the ground, allowing your lower back to stretch over the ball.","Step:5 Hold the stretch for a few seconds, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yU7w7CA.gif','https://static.exercisedb.dev/media/yU7w7CA.gif',NULL),
('yUdIGNs','cable rear delt row (stirrups)',NULL,'shoulders','delts','{"trapezius","rhomboids","biceps"}','cable',NULL,'{"Step:1 Attach a stirrup handle to a low cable pulley and stand facing the machine.","Step:2 Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.","Step:3 Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Step:4 With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.","Step:5 Pause for a moment at the top of the movement, squeezing your shoulder blade.","Step:6 Slowly release the handle back to the starting position and repeat for the desired number of repetitions.","Step:7 Switch sides and repeat the exercise with your right arm."}','https://static.exercisedb.dev/media/yUdIGNs.gif','https://static.exercisedb.dev/media/yUdIGNs.gif',NULL),
('YUYAMEj','assisted prone lying quads stretch',NULL,'legs','quads','{"hamstrings","glutes"}','other',NULL,'{"Step:1 Lie face down on the ground with your legs extended.","Step:2 Bend your left knee and reach back with your left hand to grab your left foot or ankle.","Step:3 Gently pull your left foot towards your glutes, feeling a stretch in your left quad.","Step:4 Hold the stretch for 20-30 seconds, then release.","Step:5 Repeat with your right leg."}','https://static.exercisedb.dev/media/YUYAMEj.gif','https://static.exercisedb.dev/media/YUYAMEj.gif',NULL),
('ywaNfuh','smith reverse calf raises',NULL,'legs','calves','{"hamstrings"}','machine',NULL,'{"Step:1 Adjust the smith machine bar to a height just below your shoulders.","Step:2 Stand facing the bar with your feet hip-width apart and toes pointing forward.","Step:3 Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Step:4 Hold onto the bar for support, keeping your back straight and core engaged.","Step:5 Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Step:6 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ywaNfuh.gif','https://static.exercisedb.dev/media/ywaNfuh.gif',NULL),
('YwnI4ja','cable standing inner curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Stand facing a cable machine with your feet shoulder-width apart.","Step:2 Grasp the cable handle with an underhand grip, palms facing up.","Step:3 Keep your elbows close to your sides and your upper arms stationary.","Step:4 Exhale and curl the cable handle towards your shoulders, contracting your biceps.","Step:5 Pause for a moment at the top of the movement, squeezing your biceps.","Step:6 Inhale and slowly lower the cable handle back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/YwnI4ja.gif','https://static.exercisedb.dev/media/YwnI4ja.gif',NULL),
('yWxMvB5','kettlebell thruster',NULL,'shoulders','delts','{"quadriceps","glutes","core"}','kettlebell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.","Step:2 Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.","Step:3 As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.","Step:4 Lock out your arms at the top of the movement, fully extending your elbows.","Step:5 Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yWxMvB5.gif','https://static.exercisedb.dev/media/yWxMvB5.gif',NULL),
('YZ4961r','full planche',NULL,'core','abs','{"shoulders","chest","triceps"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands shoulder-width apart and your fingers pointing forward.","Step:2 Engage your core and slowly shift your weight forward, lifting your feet off the ground.","Step:3 Continue shifting your weight forward until your body is parallel to the ground, balancing on your hands.","Step:4 Hold this position for as long as you can, maintaining a straight body line.","Step:5 Slowly lower your feet back to the ground and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/YZ4961r.gif','https://static.exercisedb.dev/media/YZ4961r.gif',NULL),
('yz9nUhF','dumbbell fly',NULL,'chest','pectorals','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Step:2 Extend your arms straight up over your chest, with a slight bend in your elbows.","Step:3 Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Step:4 Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yz9nUhF.gif','https://static.exercisedb.dev/media/yz9nUhF.gif',NULL),
('Yza7XrQ','barbell alternate biceps curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.","Step:2 Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Step:3 Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale as you slowly begin to lower the barbells back to the starting position.","Step:6 Repeat for the desired number of repetitions, alternating arms."}','https://static.exercisedb.dev/media/Yza7XrQ.gif','https://static.exercisedb.dev/media/Yza7XrQ.gif',NULL),
('yzYH9pI','barbell palms down wrist curl over a bench',NULL,'arms','forearms','{"biceps","brachialis"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.","Step:2 Hold a barbell with an overhand grip, hands shoulder-width apart.","Step:3 Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.","Step:4 Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/yzYH9pI.gif','https://static.exercisedb.dev/media/yzYH9pI.gif',NULL),
('Z5YStHW','overhead triceps stretch',NULL,'arms','triceps','{"shoulders"}','body weight',NULL,'{"Step:1 Stand or sit upright with your feet shoulder-width apart.","Step:2 Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.","Step:3 With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.","Step:4 Hold the stretch for 15-30 seconds, then release.","Step:5 Repeat on the other side."}','https://static.exercisedb.dev/media/Z5YStHW.gif','https://static.exercisedb.dev/media/Z5YStHW.gif',NULL),
('z6TAHoT','dumbbell twisting bench press',NULL,'arms','triceps','{"chest","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Hold a dumbbell in each hand with an overhand grip, palms facing away from you.","Step:3 Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Step:4 Lower the dumbbells down towards your chest, keeping your elbows close to your body.","Step:5 As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.","Step:6 Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.","Step:7 As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/z6TAHoT.gif','https://static.exercisedb.dev/media/z6TAHoT.gif',NULL),
('ZA8b5hc','kettlebell goblet squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands.","Step:2 Keeping your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.","Step:3 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:4 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZA8b5hc.gif','https://static.exercisedb.dev/media/ZA8b5hc.gif',NULL),
('za9Ni4z','barbell rack pull',NULL,'legs','glutes','{"hamstrings","lower back"}','barbell',NULL,'{"Step:1 Set up a barbell on a rack at knee height.","Step:2 Stand with your feet shoulder-width apart, toes pointing slightly outwards.","Step:3 Bend at the hips and knees to lower yourself down and grip the barbell with an overhand grip, hands shoulder-width apart.","Step:4 Engage your core and lift the barbell by extending your hips and knees, pulling your shoulders back and squeezing your glutes at the top.","Step:5 Lower the barbell back down to the starting position by bending at the hips and knees.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/za9Ni4z.gif','https://static.exercisedb.dev/media/za9Ni4z.gif',NULL),
('zCgxPbV','cable twisting pull',NULL,'back','lats','{"shoulders","biceps"}','cable',NULL,'{"Step:1 Attach a cable handle to a low pulley and stand facing the machine.","Step:2 Grasp the handle with your left hand and step away from the machine, extending your arm fully.","Step:3 Position your feet shoulder-width apart, with your knees slightly bent.","Step:4 Keep your back straight and your core engaged throughout the exercise.","Step:5 Pull the handle towards your body, rotating your torso to the right as you do so.","Step:6 Squeeze your back muscles at the end of the movement.","Step:7 Slowly return to the starting position, keeping tension on the cable.","Step:8 Repeat for the desired number of repetitions, then switch sides and perform with your right hand."}','https://static.exercisedb.dev/media/zCgxPbV.gif','https://static.exercisedb.dev/media/zCgxPbV.gif',NULL),
('zd4P4B2','stalder press',NULL,'arms','triceps','{"shoulders","core"}','body weight',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and your arms extended overhead.","Step:2 Bend your knees slightly and engage your core.","Step:3 Lower your body down into a squat position while keeping your arms extended overhead.","Step:4 As you squat down, press your arms down towards the ground, engaging your triceps.","Step:5 Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zd4P4B2.gif','https://static.exercisedb.dev/media/zd4P4B2.gif',NULL),
('Ze7MoIb','dumbbell one arm reverse grip press',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.","Step:2 Place your feet flat on the ground and keep your back straight.","Step:3 Raise the dumbbell to shoulder height, keeping your elbow close to your body.","Step:4 Press the dumbbell upwards until your arm is fully extended.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/Ze7MoIb.gif','https://static.exercisedb.dev/media/Ze7MoIb.gif',NULL),
('ZEkjZDi','kettlebell seated two arm military press',NULL,'shoulders','delts','{"triceps","upper back"}','kettlebell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a kettlebell in each hand at shoulder level with your palms facing forward.","Step:3 Press the kettlebells overhead by extending your arms fully.","Step:4 Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZEkjZDi.gif','https://static.exercisedb.dev/media/ZEkjZDi.gif',NULL),
('zfNHMN9','skater hops',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Bend your knees slightly and jump to the right, landing on your right foot.","Step:3 As you land, swing your left leg behind your right leg and tap the ground with your left toes.","Step:4 Immediately jump to the left, landing on your left foot.","Step:5 As you land, swing your right leg behind your left leg and tap the ground with your right toes.","Step:6 Continue alternating sides, jumping and tapping the ground with each leg.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zfNHMN9.gif','https://static.exercisedb.dev/media/zfNHMN9.gif',NULL),
('ZfyAGhK','cable standing rear delt row (with rope)',NULL,'shoulders','delts','{"trapezius","rhomboids","biceps"}','cable',NULL,'{"Step:1 Stand facing a cable machine with your feet shoulder-width apart.","Step:2 Hold the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.","Step:3 Keep your back straight and your core engaged.","Step:4 Pull the cable towards your body, squeezing your shoulder blades together.","Step:5 Pause for a moment at the peak of the movement, then slowly release the cable back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZfyAGhK.gif','https://static.exercisedb.dev/media/ZfyAGhK.gif',NULL),
('zFzbBfL','band push sit-up',NULL,'core','abs','{"shoulders","chest"}','resistance band',NULL,'{"Step:1 Attach the band securely to a stable anchor point.","Step:2 Lie flat on your back with your knees bent and feet flat on the ground.","Step:3 Hold the band with both hands and extend your arms straight up towards the ceiling.","Step:4 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:5 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zFzbBfL.gif','https://static.exercisedb.dev/media/zFzbBfL.gif',NULL),
('zG0zs85','barbell front squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart, toes slightly turned out.","Step:2 Hold the barbell in front of your shoulders, resting it on your collarbone and shoulders.","Step:3 Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Step:4 Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zG0zs85.gif','https://static.exercisedb.dev/media/zG0zs85.gif',NULL),
('Zg3XY7P','lever seated leg curl',NULL,'legs','hamstrings','{"calves"}','machine',NULL,'{"Step:1 Adjust the machine to fit your body and sit on it with your back against the backrest.","Step:2 Place your lower legs under the padded lever, just above your ankles.","Step:3 Grasp the handles on the sides of the machine for support.","Step:4 Keeping your upper legs stationary, exhale and curl your legs up as far as possible.","Step:5 Hold the contracted position for a brief pause as you squeeze your hamstrings.","Step:6 Inhale and slowly lower the lever back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Zg3XY7P.gif','https://static.exercisedb.dev/media/Zg3XY7P.gif',NULL),
('zGSIWQi','dumbbell lying one arm press',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.","Step:2 Hold the dumbbell at shoulder level with your palm facing forward.","Step:3 Press the dumbbell upward until your arm is fully extended.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/zGSIWQi.gif','https://static.exercisedb.dev/media/zGSIWQi.gif',NULL),
('ZgsNQ6d','inchworm',NULL,'core','abs','{"shoulders","hamstrings"}','body weight',NULL,'{"Step:1 Start in a standing position with your feet hip-width apart.","Step:2 Bend forward at the waist and place your hands on the ground in front of you.","Step:3 Walk your hands forward until you are in a high plank position, with your body in a straight line from head to toe.","Step:4 Pause for a moment, then walk your hands back towards your feet, keeping your legs as straight as possible.","Step:5 Once your hands reach your feet, stand back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZgsNQ6d.gif','https://static.exercisedb.dev/media/ZgsNQ6d.gif',NULL),
('ZgwWBoC','cable thibaudeau kayak row',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.","Step:2 Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.","Step:3 Lean forward from your hips, keeping your back straight and your abs engaged.","Step:4 Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.","Step:5 Squeeze your back muscles at the top of the movement, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides and perform with your left arm."}','https://static.exercisedb.dev/media/ZgwWBoC.gif','https://static.exercisedb.dev/media/ZgwWBoC.gif',NULL),
('ZH68exZ','band fixed back underhand pulldown',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','resistance band',NULL,'{"Step:1 Attach the band to a sturdy anchor point above your head.","Step:2 Stand facing the anchor point with your feet shoulder-width apart.","Step:3 Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step:4 Step back to create tension in the band, keeping your arms fully extended.","Step:5 Engage your core and squeeze your shoulder blades together.","Step:6 Pull the band down towards your chest, leading with your elbows.","Step:7 Pause for a moment at the bottom of the movement, feeling the contraction in your lats.","Step:8 Slowly release the tension in the band and return to the starting position.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZH68exZ.gif','https://static.exercisedb.dev/media/ZH68exZ.gif',NULL),
('zHEpuuc','cable assisted inverse leg curl',NULL,'legs','hamstrings','{"glutes","calves"}','cable',NULL,'{"Step:1 Adjust the cable machine so that the ankle attachment is at the lowest setting.","Step:2 Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.","Step:3 Hold onto the handles of the bench for stability.","Step:4 Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Step:5 Pause for a moment at the top of the movement, squeezing your hamstrings.","Step:6 Inhale and slowly lower your legs back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zHEpuuc.gif','https://static.exercisedb.dev/media/zHEpuuc.gif',NULL),
('zhF9lW4','band assisted wheel rollerout',NULL,'core','abs','{"lower back"}','resistance band',NULL,'{"Step:1 Kneel on the floor and hold the handles of the band with both hands, palms facing down.","Step:2 Place the band on the ground in front of you and position your hands shoulder-width apart.","Step:3 Engage your core and slowly roll the wheel forward, extending your body as far as you can while maintaining control.","Step:4 Pause for a moment at the furthest point, then slowly roll the wheel back towards your knees to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zhF9lW4.gif','https://static.exercisedb.dev/media/zhF9lW4.gif',NULL),
('zhMwOwE','hyperextension',NULL,'back','spine','{"glutes","hamstrings"}','body weight',NULL,'{"Step:1 Adjust the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.","Step:2 Cross your arms over your chest or place your hands behind your head.","Step:3 Lower your upper body towards the ground while keeping your back straight.","Step:4 Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zhMwOwE.gif','https://static.exercisedb.dev/media/zhMwOwE.gif',NULL),
('ziFKQXP','dumbbell one arm french press on exercise ball',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.","Step:3 Extend your arm straight up towards the ceiling, keeping your elbow stationary.","Step:4 Slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/ziFKQXP.gif','https://static.exercisedb.dev/media/ziFKQXP.gif',NULL),
('zILLZ98','smith machine bicep curl',NULL,'arms','biceps','{"forearms"}','machine',NULL,'{"Step:1 Adjust the height of the smith machine bar to be at waist level.","Step:2 Stand facing the smith machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary.","Step:5 Exhale and curl the bar up towards your shoulders, contracting your biceps.","Step:6 Pause for a moment at the top of the movement, squeezing your biceps.","Step:7 Inhale and slowly lower the bar back down to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zILLZ98.gif','https://static.exercisedb.dev/media/zILLZ98.gif',NULL),
('ZIViNh1','dumbbell reverse grip incline bench one arm row',NULL,'back','upper back','{"biceps","shoulders"}','dumbbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Place a dumbbell on the floor next to the bench.","Step:3 Stand facing the bench with your feet shoulder-width apart.","Step:4 Bend at the waist and place your left knee and left hand on the bench for support.","Step:5 Pick up the dumbbell with your right hand using a reverse grip (palm facing down).","Step:6 Keep your back straight and your core engaged.","Step:7 Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Step:8 Squeeze your back muscles at the top of the movement.","Step:9 Lower the dumbbell back down to the starting position in a controlled manner.","Step:10 Repeat for the desired number of repetitions.","Step:11 Switch sides and repeat the exercise with your left arm."}','https://static.exercisedb.dev/media/ZIViNh1.gif','https://static.exercisedb.dev/media/ZIViNh1.gif',NULL),
('zK8Fu1W','smith reverse-grip press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the height of the smith machine bar to chest level.","Step:2 Stand facing the bar with your feet shoulder-width apart.","Step:3 Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:4 Step back and position yourself with a slight bend in your knees.","Step:5 Keep your chest up and core engaged throughout the exercise.","Step:6 Lower the bar towards your chest, keeping your elbows tucked in.","Step:7 Pause for a moment at the bottom, then push the bar back up to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zK8Fu1W.gif','https://static.exercisedb.dev/media/zK8Fu1W.gif',NULL),
('zkgRrbK','hyperextension (on bench)',NULL,'back','spine','{"glutes","hamstrings"}','body weight',NULL,'{"Step:1 Adjust the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.","Step:2 Cross your arms over your chest or place your hands behind your head.","Step:3 Slowly lower your upper body towards the ground while keeping your back straight.","Step:4 Pause for a moment at the bottom, then raise your upper body back up until it is in line with your legs.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zkgRrbK.gif','https://static.exercisedb.dev/media/zkgRrbK.gif',NULL),
('znf7t8E','kipping muscle up with triple',NULL,'back','lats','{"biceps","triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:2 Engage your core and use a swinging motion to generate momentum.","Step:3 As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement. Emphasize triple control.","Step:4 Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.","Step:5 Lower yourself back down to the starting position by bending your arms and controlling the descent.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/znf7t8E.gif','https://static.exercisedb.dev/media/znf7t8E.gif',NULL),
('ZNgOYQU','vertical leg raise (on parallel bars)',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Hang from the parallel bars with your arms fully extended and your body straight.","Step:2 Engage your core and lift your legs up in front of you, keeping them straight.","Step:3 Continue lifting until your legs are parallel to the ground or slightly higher.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZNgOYQU.gif','https://static.exercisedb.dev/media/ZNgOYQU.gif',NULL),
('ZnJHhMk','lever seated crunch (chest pad)',NULL,'core','abs','{"obliques"}','machine',NULL,'{"Step:1 Adjust the seat height and chest pad position according to your comfort.","Step:2 Sit on the machine with your back against the chest pad and your feet flat on the floor.","Step:3 Grasp the handles or side bars for stability.","Step:4 Engage your abs and slowly lean back, allowing the chest pad to move with you.","Step:5 Pause for a moment at the maximum contraction, feeling the tension in your abs.","Step:6 Slowly return to the starting position by contracting your abs and pulling yourself back up.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZnJHhMk.gif','https://static.exercisedb.dev/media/ZnJHhMk.gif',NULL),
('znLogoF','barbell pullover to press',NULL,'back','lats','{"triceps","chest","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your head at one end and your feet on the ground.","Step:2 Hold the barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Step:3 Keeping your arms straight, lower the barbell behind your head in an arc-like motion until you feel a stretch in your lats.","Step:4 Pause for a moment, then reverse the motion and press the barbell back to the starting position above your chest.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/znLogoF.gif','https://static.exercisedb.dev/media/znLogoF.gif',NULL),
('znP9SIh','hug keens to chest',NULL,'legs','glutes','{"hamstrings","quadriceps"}','body weight',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart.","Step:2 Bend your knees and lower your body down into a squat position.","Step:3 As you squat down, bring your knees up towards your chest and hug them with your arms.","Step:4 Hold this position for a moment, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/znP9SIh.gif','https://static.exercisedb.dev/media/znP9SIh.gif',NULL),
('znQUdHY','dumbbell seated shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in each hand, resting on your thighs.","Step:2 Raise the dumbbells to shoulder height, palms facing forward.","Step:3 Press the dumbbells upward until your arms are fully extended overhead.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to shoulder height.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/znQUdHY.gif','https://static.exercisedb.dev/media/znQUdHY.gif',NULL),
('zoOvPcx','smith wide grip bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the bench to a comfortable position on the smith machine.","Step:2 Lie down on the bench with your feet flat on the ground.","Step:3 Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.","Step:5 Pause for a moment when the barbell touches your chest.","Step:6 Push the barbell back up to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zoOvPcx.gif','https://static.exercisedb.dev/media/zoOvPcx.gif',NULL),
('ZOuKWir','kneeling push-up (male)',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Start by kneeling on the ground with your hands shoulder-width apart, fingers pointing forward.","Step:2 Extend your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.","Step:3 Engage your core and lower your body towards the ground by bending your elbows, keeping them close to your sides.","Step:4 Continue lowering until your chest is just above the ground, then push back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZOuKWir.gif','https://static.exercisedb.dev/media/ZOuKWir.gif',NULL),
('ZqNOWQ6','lever reverse grip vertical row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and footplate position to ensure proper alignment.","Step:2 Sit on the machine with your chest against the pad and your feet flat on the footplate.","Step:3 Grasp the handles with an underhand grip, palms facing up.","Step:4 Keep your back straight and engage your core.","Step:5 Pull the handles towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZqNOWQ6.gif','https://static.exercisedb.dev/media/ZqNOWQ6.gif',NULL),
('ZsiqXYa','barbell jm bench press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Step:4 Push the barbell back up to the starting position, fully extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZsiqXYa.gif','https://static.exercisedb.dev/media/ZsiqXYa.gif',NULL),
('ZSJNetl','cable high row (kneeling)',NULL,'back','upper back','{"biceps","shoulders"}','cable',NULL,'{"Step:1 Attach a straight bar to a cable machine at chest height.","Step:2 Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.","Step:3 Sit back on your heels, keeping your back straight and your core engaged.","Step:4 Pull the bar towards your upper abdomen, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZSJNetl.gif','https://static.exercisedb.dev/media/ZSJNetl.gif',NULL),
('ZSY3MsL','self assisted inverse leg curl (on floor)',NULL,'legs','hamstrings','{"glutes","calves"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms by your sides.","Step:2 Bend your knees and place your feet flat on the ground, hip-width apart.","Step:3 Lift your hips off the ground, engaging your glutes and hamstrings.","Step:4 Slowly curl your legs towards your glutes, keeping your hips lifted.","Step:5 Pause for a moment at the top, then slowly extend your legs back to the starting position.","Step:6 Lower your hips back down to the ground.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZSY3MsL.gif','https://static.exercisedb.dev/media/ZSY3MsL.gif',NULL),
('ztAa1RK','band alternating v-up',NULL,'core','abs','{"hip flexors"}','resistance band',NULL,'{"Step:1 Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Step:2 Engage your abs and lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Step:3 As you lower your legs and upper body back down, switch the position of your legs, crossing one over the other.","Step:4 Repeat the movement, alternating the position of your legs with each repetition.","Step:5 Continue for the desired number of repetitions."}','https://static.exercisedb.dev/media/ztAa1RK.gif','https://static.exercisedb.dev/media/ztAa1RK.gif',NULL),
('ZujAdR9','cable rope incline tricep extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.","Step:2 Stand facing away from the pulley with your feet shoulder-width apart.","Step:3 Grasp the rope with an overhand grip and extend your arms straight overhead.","Step:4 Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Step:5 Lower the rope behind your head by bending your elbows until your forearms touch your biceps.","Step:6 Pause for a moment, then extend your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZujAdR9.gif','https://static.exercisedb.dev/media/ZujAdR9.gif',NULL),
('ZuPXtCK','smith hack squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the barbell on the smith machine to an appropriate height for your body.","Step:2 Stand with your feet shoulder-width apart, toes slightly pointed outwards.","Step:3 Position yourself under the barbell, resting it on your upper traps and shoulders.","Step:4 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:5 Engage your core and keep your chest up as you unrack the barbell.","Step:6 Take a step back and position your feet slightly wider than shoulder-width apart.","Step:7 Bend your knees and lower your body down, keeping your chest up and back straight.","Step:8 Continue descending until your thighs are parallel to the ground or slightly below.","Step:9 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:10 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZuPXtCK.gif','https://static.exercisedb.dev/media/ZuPXtCK.gif',NULL),
('ZuXu4Eq','v-sit on floor',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Sit on the floor with your legs extended in front of you.","Step:2 Lean back slightly and lift your legs off the ground, keeping them straight.","Step:3 Simultaneously, lift your upper body off the ground and reach your arms towards your legs.","Step:4 Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZuXu4Eq.gif','https://static.exercisedb.dev/media/ZuXu4Eq.gif',NULL),
('Zwiw7XR','dumbbell alternating bicep curl with leg raised on exercise ball',NULL,'arms','biceps','{"forearms","shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Step:2 Place an exercise ball behind you and position one foot on top of it, keeping your balance.","Step:3 With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.","Step:4 Lower the dumbbell back down to the starting position and repeat with the other arm.","Step:5 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/Zwiw7XR.gif','https://static.exercisedb.dev/media/Zwiw7XR.gif',NULL),
('ZX9UZmj','smith bent over row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Set up the smith machine with the bar at hip height.","Step:2 Stand facing the bar with your feet shoulder-width apart.","Step:3 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:4 Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:5 Pull the bar towards your lower chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZX9UZmj.gif','https://static.exercisedb.dev/media/ZX9UZmj.gif',NULL),
('ZXnjcOQ','cable one arm reverse preacher curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Adjust the cable machine so that the pulley is at the lowest position.","Step:2 Stand facing the cable machine with your feet shoulder-width apart.","Step:3 Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.","Step:4 Keep your back straight and your core engaged throughout the exercise.","Step:5 Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.","Step:6 Pause for a moment at the top of the movement, squeezing your bicep.","Step:7 Slowly lower the cable handle back to the starting position.","Step:8 Repeat for the desired number of repetitions.","Step:9 Switch arms and repeat the exercise."}','https://static.exercisedb.dev/media/ZXnjcOQ.gif','https://static.exercisedb.dev/media/ZXnjcOQ.gif',NULL),
('zYmNaoY','elevator',NULL,'back','upper back','{"shoulders","trapezius"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Place your hands on your hips or cross them in front of your chest.","Step:3 Keeping your back straight, slowly bend forward at the waist, lowering your upper body towards the ground.","Step:4 Pause for a moment at the bottom, then slowly raise your upper body back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/zYmNaoY.gif','https://static.exercisedb.dev/media/zYmNaoY.gif',NULL),
('ZZKbeMw','lever shrug',NULL,'back','traps','{"shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the leverage machine with your back against the pad.","Step:2 Grasp the handles with an overhand grip and keep your arms straight.","Step:3 Keeping your back straight, lift your shoulders up towards your ears as high as possible.","Step:4 Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ZZKbeMw.gif','https://static.exercisedb.dev/media/ZZKbeMw.gif',NULL),
('zZlORz6','dumbbell lying one arm supinated triceps extension',NULL,'arms','triceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Step:2 Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.","Step:3 Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Step:4 Pause for a moment at the bottom, then extend your arm back up to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/zZlORz6.gif','https://static.exercisedb.dev/media/zZlORz6.gif',NULL),
('ZZTGMKh','one arm against wall',NULL,'back','lats','{"shoulders","triceps"}','body weight',NULL,'{"Step:1 Stand facing a wall with your feet shoulder-width apart.","Step:2 Extend one arm straight out in front of you and place your palm against the wall.","Step:3 Engage your core and lean your body forward, keeping your arm straight and your back flat.","Step:4 Slowly push against the wall with your palm, activating your lat muscles.","Step:5 Hold the position for a few seconds, then release and repeat with the other arm."}','https://static.exercisedb.dev/media/ZZTGMKh.gif','https://static.exercisedb.dev/media/ZZTGMKh.gif',NULL)
